function persist(){try{localStorage.setItem('ila-state',JSON.stringify(state))}catch(e){}}function initials(n=state.name){return n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(s){let n=document.querySelector('.toast');if(n)n.remove();n=document.createElement('div');n.className='toast';n.textContent=s;document.body.append(n);iconify(n);clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.remove(),2800)}
