function appBase(){document.documentElement.classList.toggle('large-text',state.font>100);document.documentElement.classList.toggle('high-contrast',state.contrast);let root=document.getElementById('app');if(!state.loggedIn){root.innerHTML=login();iconify(root);bindAuth();return}root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">✿</span><span>InclusiveLearn<small>AFRICA · LEARN TOGETHER</small></span></div><div><div class="navlabel">LEARNING SPACE</div><nav class="nav">${roleNavigation().map(([t,i])=>`<button class="${view===t?'active':''}" data-view="${t}"><span class="ico">${i}</span>${t}</button>`).join('')}</nav><div class="role-space"><span class="role-space-mark">✿</span><span><small>YOUR SPACE</small><b>${esc(state.role)}</b></span></div></div><div class="sidebottom"><div class="helpbox"><b>Learning for everyone</b>Change text size, contrast or language anytime in Settings.</div><div class="profile"><div class="avatar">${initials()}</div><div style="flex:1"><b>${esc(state.name)}</b><small>${esc(state.role)} account</small></div><button class="textbtn" id="signoutSide" aria-label="Sign out">↗</button></div></div></aside><main><header class="topbar"><div class="crumb">InclusiveLearn <span style="color:#b8c4bd">/</span> <b>${esc(view)}</b></div><div class="topactions"><button class="pill ${state.offline||state.pendingSync||!navigator.onLine?'offline':'online'}" id="connect">${state.offline||state.pendingSync||!navigator.onLine?'◉ Offline · Sync pending':'● Connected'}</button><button class="pill" id="topLang">🌐 ${esc(state.language)}</button><button class="icon-button notification-trigger" id="notificationButton" aria-label="Notifications" aria-expanded="${notificationsOpen}">🔔${state.unread>0?'<span class="notification-dot"></span>':''}</button><button type="button" class="avatar signout-avatar" id="signout" title="Sign out" aria-label="Sign out">${initials()}</button></div>${notificationsOpen?notificationDropdown():''}</header><section class="page">${pageForRole()}</section></main></div>`;iconify(root);bindLegacy();bindShared()}
function login(){return `<div class="loginpage"><section class="loginvisual"><div class="brand" style="padding:0;color:white"><span class="brandmark" style="background:#ffffff22">✿</span><span>InclusiveLearn<small style="color:#c3e7d3">AFRICA · LEARN TOGETHER</small></span></div><div><div class="eyebrow" style="color:#bdebd2">LEARNING WITHOUT BARRIERS</div><h1>Every learner belongs. Every learner can grow.</h1><p>An inclusive learning space designed for African classrooms, families, and communities. Learn at your own pace, in your own way.</p></div><small style="color:#c3e7d3">Accessible · Offline-ready · Made for everyone</small></section><section class="loginform"><div class="brand" style="padding:0"><span class="brandmark">✿</span><span>InclusiveLearn<small>AFRICA · LEARN TOGETHER</small></span></div><h2>Welcome back</h2><p>Choose how you would like to explore the prototype.</p><div class="rolecards">${[['Student','🧒'],['Educator','👩🏾‍🏫'],['Parent','👨‍👧'],['Admin','🛠️']].map(([r,i])=>`<div class="rolecard ${state.role===r?'selected':''}" data-loginrole="${r}"><span>${i}</span>${r}</div>`).join('')}</div><div class="field"><label for="email">Email or phone number</label><input id="email" value="${esc(state.email||'')}" placeholder="you@example.com" type="email"></div><div class="field"><label for="password">Password</label><input id="password" placeholder="Enter any password" type="password"></div><button class="btn" id="loginbtn" onclick="state.email=document.getElementById('email').value||'learner@example.com';state.name={Student:'Amina Yusuf',Educator:'Ms. Ndlovu',Parent:'Sam Yusuf',Admin:'Platform Admin'}[state.role];state.loggedIn=true;persist();app()" style="width:100%;margin-top:8px">Sign in to your space →</button><button class="textbtn" id="explore" onclick="state.role='Student';state.name='Amina Yusuf';state.loggedIn=true;persist();app()" style="width:100%;padding:15px">Explore as a learner without signing in</button><div class="notice"><span>🔒</span><span>Prototype preview. Your demo data stays in this browser.</span></div></section></div>`}
function timeGreeting(now=new Date()){const hour=now.getHours();return hour<12?'Good morning':hour<17?'Good afternoon':'Good evening'}
function studentHomeBase(){let educatorMessage=[...remoteMessages,...platform.messages].filter(m=>m.toRole==='Student'&&m.fromRole==='Educator'&&(!state.accountId||m.toUserId===state.accountId)).sort((a,b)=>(Date.parse(b.time)||0)-(Date.parse(a.time)||0))[0]||{from:'Your educator',text:'No messages yet. Messages from your educator will appear here.',time:''};let done=Object.values(state.progress).filter(v=>v>=100).length;return `<div class="welcome"><div><div class="eyebrow" data-student-date>${new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'})}</div><h1 data-student-greeting>${timeGreeting()}, ${esc(state.name.split(' ')[0])} 👋</h1><p>A little learning each day makes a big difference.</p></div><button class="btn" data-view="My learning">Explore lessons →</button></div><div class="grid stats"><div class="card stat"><div><div class="label">Lessons completed</div><div class="value">${done}</div><div class="hint">Completed lessons</div></div><div class="staticon">📖</div></div><div class="card stat"><div><div class="label">Learning streak</div><div class="value">5 days</div><div class="hint">You're on a roll!</div></div><div class="staticon">🔥</div></div><div class="card stat"><div><div class="label">Time this week</div><div class="value">2.4h</div><div class="hint">Goal: 3 hours</div></div><div class="staticon">⏱️</div></div><div class="card stat"><div><div class="label">Saved offline</div><div class="value">${state.saved.length}</div><div class="hint">Ready without internet</div></div><div class="staticon">⬇️</div></div></div><div class="grid cols"><div class="grid" style="align-content:start"><div class="hero"><div class="eyebrow">PICK UP WHERE YOU LEFT OFF</div><h2>How plants grow</h2><p>Explore the journey from a tiny seed to a thriving plant. Your lesson is saved and ready whenever you are.</p><button class="btn" data-lesson="plants">Continue learning <span aria-hidden="true">→</span></button></div><div><div class="sectionhead"><h2>Recommended for you</h2><button class="textbtn" data-view="My learning">View all</button></div><div class="lesson-list">${[lessons[1],lessons[3],lessons[2]].map(lessonRow).join('')}</div></div></div><div class="rightstack"><div class="card streak"><div class="sectionhead"><h2>Your learning streak</h2><span>🔥</span></div><div class="streakbig"><span>🔥</span><div><strong>5 days</strong><small>Keep showing up!</small></div></div><div class="days">${['M','T','W','T','F','S','S'].map((d,i)=>`<span><i class="${i<5?'done':''}">${i<5?'✓':d}</i>${d}</span>`).join('')}</div></div><div class="card"><div class="sectionhead"><h2>Weekly learning goal</h2><span>🎯</span></div><div class="goal"><div class="ring"></div><div><b style="font-size:13px">2.2 of 3 hours</b><p>You're almost there. Keep it up!</p></div></div><div class="progress"><i style="width:72%"></i></div></div><div class="card"><div class="sectionhead"><h2>From your educator</h2><span>💌</span></div><div class="message"><div class="avatar">${initials(educatorMessage.from)}</div><div><b>${esc(educatorMessage.from)}</b><p>${esc(educatorMessage.text)}</p><small>${esc(educatorMessage.time)}</small></div></div><button class="textbtn" data-view="Messages">Open messages →</button></div></div></div>`}
function lessonRow(l){let p=state.progress[l.id]??l.progress;return `<div class="lesson"><div class="lessonart">${l.icon}</div><div class="lessoninfo"><b>${l.title}</b><small>${l.subject} · ${l.grade} · ${l.time}</small><div class="progress"><i style="width:${p}%"></i></div></div><button class="arrow" data-lesson="${l.id}" aria-label="Open ${l.title}">→</button></div>`}
function catalog(){let list=lessons.filter(l=>(filter==='All subjects'||l.subject===filter)&&l.title.toLowerCase().includes(query.toLowerCase()));return `<div class="welcome"><div><div class="eyebrow">${state.role==='Educator'?'CLASSROOM CONTENT':'YOUR LEARNING SPACE'}</div><h1>${state.role==='Educator'?'Content library':'My learning'} 📚</h1><p>${state.role==='Educator'?'Find accessible lessons to share with your classroom.':'Choose a lesson that interests you. Learn at your own pace.'}</p></div><button class="btn soft" data-view="Offline library">↓ Saved offline (${state.saved.length})</button></div><div class="toolbar" style="margin-bottom:20px"><input id="search" class="search" placeholder="Search lessons..." value="${esc(query)}" aria-label="Search lessons"><select id="subjectfilter" class="filter">${['All subjects',...new Set(lessons.map(x=>x.subject))].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><span class="chip">${list.length} lessons</span></div><div class="grid catalog">${list.length?list.map(courseCard).join(''):'<div class="card">No lessons match. Try another search.</div>'}</div>`}
function cacheResourceMedia(item){if(!('caches'in window))return;for(let value of [item.audioUrl,item.videoUrl]){let url=safeMediaUrl(value);if(!url||new URL(url).origin!==location.origin)continue;caches.open('ila-content-offline').then(cache=>cache.add(url)).catch(()=>{})}}
function resourceFormat(item){return item.videoUrl?'Video':item.audioUrl?'Audio':'Text'}
function safeMediaUrl(value){try{let url=new URL(String(value||''),location.href);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}}
function videoPlayer(url,title='Lesson video'){let safe=safeMediaUrl(url);if(!safe)return '';let parsed=new URL(safe),youtube=parsed.hostname==='youtu.be'||parsed.hostname==='youtube.com'||parsed.hostname.endsWith('.youtube.com'),vimeo=parsed.hostname==='vimeo.com'||parsed.hostname.endsWith('.vimeo.com');if(youtube){let id=parsed.hostname==='youtu.be'?parsed.pathname.slice(1):parsed.pathname==='/watch'?parsed.searchParams.get('v'):parsed.pathname.split('/').filter(Boolean).pop();if(!/^[\w-]{6,20}$/.test(id||''))return '';let origin=encodeURIComponent(location.origin),embed=`https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?origin=${origin}`,watch=`https://www.youtube.com/watch?v=${encodeURIComponent(id)}`;return `<div class="media-resource"><b>${esc(title)}</b><iframe class="lesson-video-embed" src="${embed}" title="${esc(title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="origin"></iframe><a class="video-fallback-link" href="${watch}" target="_blank" rel="noopener noreferrer">Having trouble playing? Watch on YouTube ↗</a></div>`}if(vimeo){let id=parsed.pathname.split('/').filter(Boolean).pop();if(!/^\d+$/.test(id||''))return '';return `<div class="media-resource"><b>${esc(title)}</b><iframe class="lesson-video-embed" src="https://player.vimeo.com/video/${id}" title="${esc(title)}" loading="lazy" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="origin"></iframe></div>`}return `<div class="media-resource"><b>${esc(title)}</b><video controls preload="metadata" playsinline src="${esc(safe)}">Your browser does not support video playback.</video></div>`}
function courseCard(l){let p=state.progress[l.id]??l.progress,lang=l.lang||'English';return `<article class="card course"><div class="coursecover">${l.icon}<span class="chip ${l.tag==='Completed'?'green':''}" style="position:absolute;left:13px;top:13px">${esc(l.tag)}</span></div><div class="coursebody"><div class="eyebrow">${esc(l.subject)} · ${esc(l.grade)} · ${esc(lang)}</div><h3>${esc(l.title)}</h3><p>${esc(l.desc)}</p><div class="coursefoot"><span class="chip">${esc(resourceFormat(l))} · ◷ ${esc(l.time)}</span><button class="btn small" data-lesson="${esc(l.id)}">${p>=100?'Review':p?'Continue':'Start lesson'} →</button></div><div class="progress"><i style="width:${p}%"></i></div><button type="button" class="textbtn offline-save-link" data-save-lesson="${esc(l.id)}">${state.saved.includes(l.id)?'✓ Saved offline':'↓ Save for offline use'}</button></div></article>`}
function offlinePage(){let saved=lessons.filter(l=>state.saved.includes(l.id)),savedCustom=Object.values(state.savedResources||{});return `<div class="welcome"><div><div class="eyebrow">LEARN ANYWHERE</div><h1>Offline library ↓</h1><p>These lessons are saved on this device and ready without internet.</p></div><span class="chip ${state.offline?'gold':'green'}">${state.offline?'Offline mode':'● Device ready'}</span></div><div class="notice"><span>🔄</span><span><strong>Progress sync</strong><br>Your learning activity is saved on this device. When you reconnect, it will sync automatically.</span></div><div class="grid catalog" style="margin-top:20px">${saved.length?saved.map(courseCard).join(''):''}${savedCustom.length?contentCards(savedCustom):''}${saved.length||savedCustom.length?'':'<div class="card"><h3>No saved lessons yet</h3><p>Browse the library and save learning materials to this device.</p><button class="btn" data-view="My learning">Browse lessons →</button></div>'}</div>`}
function progressPage(){let rows=lessons.filter(l=>state.progress[l.id]!==undefined||l.progress>0);return `<div class="welcome"><div><div class="eyebrow">YOUR ACHIEVEMENTS</div><h1>Progress & reports 📈</h1><p>See how far you've come and what to explore next.</p></div><button class="btn light" id="downloadReport">↓ Download report</button></div><div class="grid stats"><div class="card stat"><div><div class="label">Lessons completed</div><div class="value">${Object.values(state.progress).filter(v=>v>=100).length+3}</div><div class="hint">Across 3 subjects</div></div><div class="staticon">✓</div></div><div class="card stat"><div><div class="label">Average quiz score</div><div class="value">86%</div><div class="hint">↑ 8% this month</div></div><div class="staticon">✎</div></div><div class="card stat"><div><div class="label">Learning time</div><div class="value">8.5h</div><div class="hint">This month</div></div><div class="staticon">◷</div></div><div class="card stat"><div><div class="label">Skills growing</div><div class="value">6</div><div class="hint">Across 3 subjects</div></div><div class="staticon">🌿</div></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Lesson progress</h2><span class="chip">This term</span></div>${rows.map(l=>`<div class="settingrow"><div class="lessonart" style="width:43px;height:43px;flex:0 0 43px">${l.icon}</div><div style="flex:1"><b>${l.title}</b><p>${l.subject} · ${l.grade}</p><div class="progress"><i style="width:${state.progress[l.id]??l.progress}%"></i></div></div><strong>${state.progress[l.id]??l.progress}%</strong></div>`).join('')}</div><div class="rightstack"><div class="card"><div class="sectionhead"><h2>Skills I'm growing</h2><span>🌱</span></div>${[['Reading','78%'],['Problem solving','65%'],['Curiosity','92%']].map(([n,v])=>`<div class="settingrow"><div style="flex:1"><b>${n}</b><div class="progress"><i style="width:${v}"></i></div></div><small>${v}</small></div>`).join('')}</div><div class="card"><div class="sectionhead"><h2>Share with family</h2><span>👨‍👩‍👧</span></div><p style="font-size:12px;color:var(--muted);line-height:1.6">Your family and educator can follow your progress and celebrate your achievements.</p><button class="btn soft" data-view="Messages">Send an update →</button></div></div></div>`}function educatorPage(){return `<div class="welcome"><div><div class="eyebrow">EDUCATOR SPACE · GRADE 5</div><h1>Your classroom, Ms. Ndlovu 👩🏾‍🏫</h1><p>See how your learners are doing and help everyone move forward.</p></div><button class="btn" id="assignBtn">＋ Create assignment</button></div><div class="grid stats"><div class="card stat"><div><div class="label">My learners</div><div class="value">24</div><div class="hint">Across 1 classroom</div></div><div class="staticon">🧒</div></div><div class="card stat"><div><div class="label">Tasks to review</div><div class="value">6</div><div class="hint">3 submitted today</div></div><div class="staticon">📝</div></div><div class="card stat"><div><div class="label">Class participation</div><div class="value">82%</div><div class="hint">↑ 6% this week</div></div><div class="staticon">📊</div></div><div class="card stat"><div><div class="label">Active lessons</div><div class="value">8</div><div class="hint">Across 4 subjects</div></div><div class="staticon">📚</div></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Class progress</h2><button class="textbtn" id="classReport">Download report</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Learner</th><th>Recent lesson</th><th>Progress</th><th>Support</th></tr></thead><tbody>${[['Amina Yusuf','How plants grow','78%','On track','AY'],['Daniel Moyo','Fractions around us','42%','Needs check-in','DM'],['Lebo Nkosi','Stories from our home','91%','On track','LN'],['Grace Kamau','Our precious water','58%','On track','GK']].map((r,i)=>`<tr><td><div class="studentcell"><span class="miniav">${r[4]}</span>${r[0]}</div></td><td>${r[1]}</td><td><div class="progress" style="width:100px"><i style="width:${r[2]}"></i></div><small>${r[2]}</small></td><td><span class="chip ${i===1?'gold':'green'}">${r[3]}</span></td></tr>`).join('')}</tbody></table></div></div><div class="rightstack"><div class="card"><div class="sectionhead"><h2>Classroom tools</h2><span>🧰</span></div><button class="btn soft" style="width:100%;margin:4px 0" id="assignBtn2">＋ Assign a lesson</button><button class="btn light" style="width:100%;margin:4px 0" data-view="My learning">Browse content library</button><button class="btn light" style="width:100%;margin:4px 0" data-view="Messages">Message families</button></div><div class="card"><div class="sectionhead"><h2>Needs your support</h2><span>💛</span></div><div class="message"><div class="avatar">DM</div><div><b>Daniel Moyo</b><p>Has not opened the fractions assignment yet.</p><button class="textbtn" data-view="Messages">Send a check-in →</button></div></div></div></div></div>`}
function parentPage(){return `<div class="welcome"><div><div class="eyebrow">FAMILY SPACE</div><h1>Hello, ${esc(state.name.split(' ')[0])} 👋</h1><p>Celebrate learning together. Here's Amina's progress this week.</p></div><button class="btn" data-view="Messages">✉ Message educator</button></div><div class="grid stats"><div class="card stat"><div><div class="label">Lessons this week</div><div class="value">4</div><div class="hint">Amina is building a habit</div></div><div class="staticon">📖</div></div><div class="card stat"><div><div class="label">Learning time</div><div class="value">2.4h</div><div class="hint">Goal: 3 hours</div></div><div class="staticon">⏱️</div></div><div class="card stat"><div><div class="label">Current streak</div><div class="value">5 days</div><div class="hint">Keep encouraging her!</div></div><div class="staticon">🔥</div></div><div class="card stat"><div><div class="label">Educator messages</div><div class="value">1</div><div class="hint">Latest today</div></div><div class="staticon">💌</div></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Amina's learning this week</h2><button class="textbtn" data-view="Progress">Full report →</button></div>${[['🌱','How plants grow','Science','65%'],['📚','Stories from our home','Reading','100%'],['💧','Our precious water','Science','20%']].map(([e,t,s,p])=>`<div class="settingrow"><span class="lessonart" style="width:43px;height:43px;flex:0 0 43px">${e}</span><div style="flex:1"><b>${t}</b><p>${s} · This week</p><div class="progress"><i style="width:${p}"></i></div></div><strong>${p}</strong></div>`).join('')}</div><div class="rightstack"><div class="card" style="background:#fff7e8"><div class="sectionhead"><h2>A little encouragement</h2><span>💛</span></div><p style="font-size:13px;color:#745d40;line-height:1.7">Ask Amina what she discovered about plants today. A curious question can make learning feel special.</p><button class="btn" id="encourage">Send a kind message</button></div><div class="card"><div class="sectionhead"><h2>From the educator</h2><span>👩🏾‍🏫</span></div><div class="message"><div class="avatar">MN</div><div><b>Ms. Ndlovu</b><p>Great work on the plant journal this week. Amina is asking thoughtful questions in class!</p><small>Today · 9:15 am</small></div></div><button class="textbtn" data-view="Messages">Reply to educator →</button></div></div></div>`}
function adminPage(){return `<div class="welcome"><div><div class="eyebrow">PLATFORM ADMINISTRATION</div><h1>Welcome, ${esc(state.name.split(' ')[0])} 🛠️</h1><p>Monitor platform activity and keep learning resources safe and accessible.</p></div><button class="btn" id="exportData">↓ Export platform report</button></div><div class="grid stats"><div class="card stat"><div><div class="label">Registered users</div><div class="value">1,248</div><div class="hint">Across 8 learning centres</div></div><div class="staticon">👥</div></div><div class="card stat"><div><div class="label">Active this week</div><div class="value">876</div><div class="hint">70% weekly activity</div></div><div class="staticon">●</div></div><div class="card stat"><div><div class="label">Published lessons</div><div class="value">96</div><div class="hint">Across 5 subjects</div></div><div class="staticon">📚</div></div><div class="card stat"><div><div class="label">Needs review</div><div class="value">3</div><div class="hint">Content submissions</div></div><div class="staticon">🔎</div></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Content moderation</h2><span class="chip gold">3 awaiting review</span></div>${[['“The animal world”','Submitted by J. Banda','Grade 4 · Science'],['“My community helpers”','Submitted by P. Otieno','Grade 3 · Life Skills'],['“Counting with seeds”','Submitted by L. Mensah','Grade 2 · Mathematics']].map(([a,b,c])=>`<div class="settingrow"><div style="flex:1"><b>${a}</b><p>${b} · ${c}</p></div><button class="btn small reviewBtn">Review</button></div>`).join('')}</div><div class="rightstack"><div class="card"><div class="sectionhead"><h2>System health</h2><span class="chip green">All services active</span></div>${[['Learning library','● Active'],['Offline sync service','● Active'],['Accessibility tools','● Active'],['Messaging','● Active']].map(([a,b])=>`<div class="settingrow"><b>${a}</b><span style="font-size:11px;color:var(--green)">${b}</span></div>`).join('')}</div><div class="card"><div class="sectionhead"><h2>Quick actions</h2><span>⚙</span></div><button class="btn light" style="width:100%" data-view="My learning">Manage learning content</button><button class="btn light" style="width:100%;margin-top:8px" data-view="Progress">View usage reports</button></div></div></div>`}
function messagesPage(){let threads=state.messages.map(m=>`<div class="message"><div class="avatar">${m.from==='Ms. Ndlovu'?'MN':m.from==='You'?'AY':'🏠'}</div><div style="flex:1"><b>${esc(m.from)}</b><p>${esc(m.text)}</p><small>${esc(m.time)}</small></div></div>`).join('');return `<div class="welcome"><div><div class="eyebrow">STAY CONNECTED</div><h1>Messages ✉</h1><p>Talk with educators and family, all in one friendly space.</p></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Your conversations</h2><span class="chip green">${state.messages.length} messages</span></div>${threads}<form id="messageForm"><div class="field"><label for="messageText">Write a message</label><textarea id="messageText" rows="3" placeholder="Share a question, update, or celebration..."></textarea></div><button class="btn">Send message →</button></form></div><div class="rightstack"><div class="card"><h2 style="font-size:16px;margin-top:0">Your learning community</h2><div class="message"><div class="avatar">MN</div><div><b>Ms. Ndlovu</b><p>Class educator · usually replies within one school day</p></div></div><div class="message"><div class="avatar">🏠</div><div><b>Family circle</b><p>Your parent or guardian can see your progress updates</p></div></div><div class="notice"><span>💚</span><span>Messages are here to help everyone feel connected and supported.</span></div></div></div></div>`}
function settingsPage(){return `<div class="welcome"><div><div class="eyebrow">MAKE IT YOURS</div><h1>Accessibility & settings ⚙</h1><p>Choose the learning tools that feel right for you.</p></div><button class="btn" id="saveSettings">Save preferences</button></div><div class="settings"><div class="card settingnav"><button class="active">Accessibility</button><button data-setting="language">Language</button><button data-setting="profile">My profile</button><button data-setting="privacy">Privacy & consent</button></div><div class="card"><div class="sectionhead"><div><h2>Comfortable learning</h2><small style="color:var(--muted)">Settings are saved on this device.</small></div><span>♿</span></div><div class="settingrow"><div><b>Larger text</b><p>Make words easier to read across the app.</p></div><select id="fontSize" class="filter"><option value="100" ${state.font===100?'selected':''}>Standard</option><option value="112" ${state.font===112?'selected':''}>Large</option><option value="125" ${state.font===125?'selected':''}>Extra large</option></select></div><div class="settingrow"><div><b>High contrast</b><p>Increase contrast between text and background.</p></div><input id="contrastToggle" class="toggle" type="checkbox" ${state.contrast?'checked':''} aria-label="High contrast"></div><div class="settingrow"><div><b>Read aloud (text-to-speech)</b><p>Listen to lesson text using your device's voice.</p></div><input id="ttsToggle" class="toggle" type="checkbox" ${state.tts?'checked':''} aria-label="Read aloud"></div><div class="settingrow"><div><b>Speech input (speech-to-text)</b><p>Use your voice to write answers when your browser supports it.</p></div><input id="sttToggle" class="toggle" type="checkbox" ${state.stt?'checked':''} aria-label="Speech input"></div><div class="settingrow"><div><b>Learning language</b><p>Choose your preferred language for menus.</p></div><select class="filter" id="languageSelect">${['English','Yorùbá','Kiswahili','Français'].map(x=>`<option ${state.language===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="notice"><span>🔐</span><span><strong>Your data, your choice.</strong><br>This prototype stores preferences in your browser. In a full release you can review, download, or remove your information anytime.</span></div></div></div>`}
function lessonPage(id){let l=lessons.find(x=>x.id===id)||lessons[0],d=lessonDetails[l.id],p=state.progress[l.id]??l.progress,index=lessons.indexOf(l)+1;return `<div class="welcome"><div><button class="textbtn" data-view="My learning">← Back to my learning</button><div class="eyebrow" style="margin-top:14px">${esc(l.subject)} · ${esc(l.grade)} · ${esc(l.lang||'English')} · ${esc(l.time)}</div><h1>${esc(l.title)}</h1><p>${esc(l.desc)}</p></div><div class="toolbar"><button class="btn soft" id="saveOffline">${state.saved.includes(l.id)?'✓ Saved offline':'↓ Save offline'}</button></div></div><div class="lessonhero"><div class="emoji">${l.icon}</div><div><span class="chip green">${p>=100?'Completed':p?'In progress':'Ready to begin'}</span><h1>${esc(l.title)}</h1><p style="margin:0;color:var(--muted);font-size:12px">A friendly, step-by-step learning activity</p></div></div><div class="grid cols lesson-layout"><article class="card lessontext"><div class="toolbar lesson-toolbar"><span class="chip">Lesson ${index} of ${lessons.length}</span><div class="read-controls"><button class="btn soft" id="readAloud" aria-label="Play lesson aloud" aria-pressed="false"><span aria-hidden="true">▶</span> <span class="player-label">Play aloud</span></button><button class="btn light" id="stopReadAloud" aria-label="Stop read aloud" disabled><span aria-hidden="true">■</span> Stop</button></div></div><div class="lesson-narration" id="lessonNarration"><h2>${esc(d.heading)}</h2>${d.body.map(text=>`<p>${esc(text)}</p>`).join('')}<div class="notice"><span>✦</span><span><strong>Pause and think</strong><br>${esc(d.think)}</span></div><h2>Try it yourself</h2><p>${esc(d.activity)}</p></div><div class="quiz"><div class="quiz-head"><div><div class="eyebrow">QUICK CHECK · 5 QUESTIONS</div><p class="quiz-intro">Choose the best answer for each question, then check your understanding.</p></div><span class="quiz-count">5 questions</span></div>${lessonQuizzes[l.id].map((item,i)=>`<fieldset class="quiz-question" data-question="${i}"><legend><span class="question-number">${String(i+1).padStart(2,'0')}</span>${esc(item.q)}</legend>${item.o.map((option,j)=>`<label class="answer"><input type="radio" name="quiz-${i}" value="${j}"> ${esc(option)}</label>`).join('')}<div class="question-feedback" aria-live="polite"></div></fieldset>`).join('')}<button class="btn" id="checkAnswer">Check my answers →</button><div id="quizResult" aria-live="polite"></div></div></article><aside class="rightstack"><div class="card"><div class="sectionhead"><h2>Lesson progress</h2><span>${p}%</span></div><div class="progress"><i style="width:${p}%"></i></div><p style="font-size:11px;color:var(--muted)">You're doing great. Take your time and enjoy learning.</p><button class="btn" id="markComplete" style="width:100%">${p>=100?'✓ Completed':'Mark lesson complete'}</button></div><div class="card"><div class="sectionhead"><h2>Learning tools</h2><span>♿</span></div><p class="player-help">Use Play aloud to listen, Pause to take a break, or Stop to start over.</p><div class="settingrow"><div><b>Text size</b><p>${state.font>100?'Large and clear':'Standard'}</p></div><button class="textbtn" data-view="Settings">Change</button></div><div class="settingrow"><div><b>Language</b><p>${esc(state.language)}</p></div><button class="textbtn" data-view="Settings">Change</button></div></div><div class="card"><b style="font-size:13px">Learning offline?</b><p style="font-size:11px;color:var(--muted);line-height:1.6">Save this lesson now and keep learning even when the internet is unavailable.</p><button class="textbtn" id="saveOffline2">↓ Save to device</button></div></aside></div>`}function educatorReportsPage(){let students=classroomRoster,average=students.length?Math.round(students.reduce((sum,student)=>sum+Object.values(student.progress||{}).reduce((a,v)=>a+Number(v),0)/Math.max(1,Object.keys(student.progress||{}).length),0)/students.length):0,completed=students.reduce((sum,student)=>sum+Number(student.completed||0),0);return `<div class="welcome"><div><div class="eyebrow">EDUCATOR REPORTS</div><h1>Class learning report</h1><p>Progress is synchronized from student accounts when they reconnect.</p></div><button class="btn light" id="classReport">↓ Download report</button></div><div class="grid stats"><div class="card stat"><div><div class="label">Student accounts</div><div class="value">${students.length}</div><div class="hint">Connected learner profiles</div></div><div class="staticon">♙</div></div><div class="card stat"><div><div class="label">Average module progress</div><div class="value">${average}%</div><div class="hint">Across enrolled students</div></div><div class="staticon">↗</div></div><div class="card stat"><div><div class="label">Modules completed</div><div class="value">${completed}</div><div class="hint">Saved across accounts</div></div><div class="staticon">✓</div></div><div class="card stat"><div><div class="label">Messages to review</div><div class="value">${inboxMessages().filter(message=>message.toRole==='Educator').length}</div><div class="hint">Open your inbox</div></div><div class="staticon">✉</div></div></div><div class="card"><div class="sectionhead"><h2>Student progress</h2><span class="chip">${students.length} learners</span></div>${students.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Learner</th><th>Completed modules</th><th>Average progress</th><th>Last synced</th></tr></thead><tbody>${students.map(student=>{let values=Object.values(student.progress||{}),avg=values.length?Math.round(values.reduce((a,v)=>a+Number(v),0)/values.length):0;return `<tr><td>${esc(student.name)}</td><td>${Number(student.completed||0)}</td><td><div class="progress" style="width:110px"><i style="width:${avg}%"></i></div><small>${avg}%</small></td><td>${student.updatedAt?new Date(student.updatedAt).toLocaleString():'Not synced yet'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty-state"><b>No student accounts connected yet</b><p>Student progress will appear here after learners create accounts and complete lessons.</p></div>'}</div>`}
function pageForRole(){const allowed=roleNavigation().map(([label])=>label);if(view.startsWith('Lesson:'))return state.role==='Student'?lessonPage(view.split(':')[1]):(view='Home',pageForRole());if(!allowed.includes(view))view='Home';if(view==='Settings')return settingsPage();if(view==='Messages')return messagesPage();if(state.role==='Student'){if(view==='My learning')return catalog();if(view==='Offline library')return offlinePage();if(view==='Progress')return progressPage();return studentHome()}if(state.role==='Educator'){if(view==='Content library')return catalog();if(view==='Reports')return educatorReportsPage();return educatorPage()}if(state.role==='Parent')return view==='Child progress'?parentProgressPage():parentPage();if(state.role==='Admin'){if(view==='Content review')return adminReviewPage();if(view==='Usage reports')return adminUsagePage();return adminPage()}return studentHome()}
function bindLegacy(){document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{stopReadAloud(false);view=b.dataset.view;notificationsOpen=false;app();window.scrollTo(0,0)}));document.querySelectorAll('[data-lesson]').forEach(b=>b.addEventListener('click',()=>{stopReadAloud(false);view='Lesson:'+b.dataset.lesson;notificationsOpen=false;app();window.scrollTo(0,0)}));document.querySelectorAll('[data-loginrole]').forEach(b=>b.addEventListener('click',()=>{state.role=b.dataset.loginrole;app()}));let loginbtn=document.getElementById('loginbtn'),explore=document.getElementById('explore');if(loginbtn)loginbtn.onclick=()=>{state.email=document.getElementById('email').value||'learner@example.com';let roleName={Student:'Amina Yusuf',Educator:'Ms. Ndlovu',Parent:'Sam Yusuf',Admin:'Platform Admin'};state.name=roleName[state.role];state.loggedIn=true;persist();app()};if(explore)explore.onclick=()=>{state.role='Student';state.name='Amina Yusuf';state.loggedIn=true;persist();app()};document.getElementById('signout')?.addEventListener('click',logoutAccount);document.getElementById('connect')?.addEventListener('click',()=>{state.offline=!state.offline;persist();app();toast(state.offline?'Offline mode on · Your progress is saved here':'Connection restored · Syncing your learning progress')});document.getElementById('topLang')?.addEventListener('click',()=>{view='Settings';app()});document.getElementById('search')?.addEventListener('input',e=>{query=e.target.value;let pos=e.target.selectionStart;app();let n=document.getElementById('search');n.focus();n.setSelectionRange(pos,pos)});document.getElementById('subjectfilter')?.addEventListener('change',e=>{filter=e.target.value;app()});document.getElementById('saveOffline')?.addEventListener('click',saveCurrent);document.getElementById('saveOffline2')?.addEventListener('click',saveCurrent);document.getElementById('markComplete')?.addEventListener('click',()=>{let id=view.split(':')[1];state.progress[id]=100;state.completion++;persist();app();toast('Lesson complete! Your progress is saved 🌟')});document.getElementById('readAloud')?.addEventListener('click',speakLesson);document.getElementById('stopReadAloud')?.addEventListener('click',()=>stopReadAloud(true));document.getElementById('checkAnswer')?.addEventListener('click',(event)=>{if(event.currentTarget.dataset.retake==='true'){document.querySelectorAll('.quiz-question input').forEach(input=>{input.checked=false;input.disabled=false});document.querySelectorAll('.question-feedback').forEach(feedback=>feedback.innerHTML='');document.getElementById('quizResult').innerHTML='';event.currentTarget.dataset.retake='false';event.currentTarget.textContent='Check my answers →';event.currentTarget.disabled=false;return}let id=view.split(':')[1],items=lessonQuizzes[id],result=document.getElementById('quizResult'),score=0,unanswered=[];items.forEach((item,i)=>{let selected=document.querySelector(`input[name="quiz-${i}"]:checked`),feedback=document.querySelector(`[data-question="${i}"] .question-feedback`);if(!selected){unanswered.push(i+1);return}let correct=Number(selected.value)===item.a;if(correct)score++;feedback.innerHTML=`<p class="${correct?'quiz-correct':'quiz-retry'}">${correct?'Correct.':'Review this one.'} ${esc(item.why)}</p>`});if(unanswered.length){result.innerHTML=`<p class="quiz-retry">Please answer question${unanswered.length===1?'':'s'} ${unanswered.join(', ')} before checking.</p>`;return}result.innerHTML=`<p class="quiz-score">You scored <strong>${score} out of 5</strong>. ${score===5?'Excellent work!':score>=3?'Good effort—review any answers you missed.':'Keep learning, then try this check again.'}</p>`;document.querySelectorAll('.quiz-question input').forEach(input=>input.disabled=true);let check=document.getElementById('checkAnswer');check.dataset.retake='true';check.textContent='Retake quiz ↻';check.disabled=false;state.progress[id]=Math.max(state.progress[id]||0,score*20);persist()});document.getElementById('fontSize')?.addEventListener('change',e=>{state.font=Number(e.target.value);document.documentElement.classList.toggle('large-text',state.font>100)});document.getElementById('contrastToggle')?.addEventListener('change',e=>{state.contrast=e.target.checked;document.documentElement.classList.toggle('high-contrast',state.contrast)});document.getElementById('ttsToggle')?.addEventListener('change',e=>state.tts=e.target.checked);document.getElementById('sttToggle')?.addEventListener('change',e=>state.stt=e.target.checked);document.getElementById('languageSelect')?.addEventListener('change',e=>state.language=e.target.value);document.getElementById('saveSettings')?.addEventListener('click',()=>{state.guardianContact=document.getElementById('guardianContact')?.value.trim()||'';persist();app();toast('Your preferences are saved')});document.getElementById('messageForm')?.addEventListener('submit',e=>{e.preventDefault();let m=document.getElementById('messageText').value.trim();if(!m)return toast('Write a message before sending');state.messages.unshift({from:'You',text:m,time:'Just now'});persist();app();toast('Message sent to your learning community')});document.getElementById('downloadReport')?.addEventListener('click',downloadReport);document.getElementById('classReport')?.addEventListener('click',downloadReport);document.getElementById('exportData')?.addEventListener('click',downloadReport);document.getElementById('assignBtn')?.addEventListener('click',createAssignment);document.getElementById('assignBtn2')?.addEventListener('click',createAssignment);document.getElementById('encourage')?.addEventListener('click',()=>{state.messages.unshift({from:'Sam Yusuf',text:'I’m proud of you, Amina! Keep being curious and doing your best. 💛',time:'Just now'});persist();toast('A kind message is on its way 💛')});document.querySelectorAll('.reviewBtn').forEach(b=>b.onclick=()=>modal('Review learning content','This sample submission is accessible and ready to publish.','Publish lesson',()=>{b.closest('.settingrow').remove();toast('Lesson approved and added to the library')}));document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{if(b.dataset.setting==='language')document.getElementById('languageSelect')?.scrollIntoView({behavior:'smooth'});else toast('This profile section is part of the demo account.')})}
function cacheLessonCopy(id){let lesson=lessons.find(item=>item.id===id);if(!lesson)return;try{if('caches'in window)caches.open('ila-content-offline').then(cache=>cache.put(new Request(`${location.origin}/offline-lessons/${encodeURIComponent(id)}.json`),new Response(JSON.stringify({lesson,details:lessonDetails[id],quiz:lessonQuizzes[id]}),{headers:{'Content-Type':'application/json'}})))}catch{}}
function saveLessonOffline(id,refresh=true){let lesson=lessons.find(item=>item.id===id);if(!lesson)return toast('This resource cannot be saved offline yet.');state.saved=state.saved||[];if(!state.saved.includes(id))state.saved.push(id);cacheLessonCopy(id);persist();if(refresh)app();toast('Lesson saved on this device for offline learning')}
function saveCurrent(){saveLessonOffline(view.split(':')[1])}
function updateNarrationControls(){let play=document.getElementById('readAloud'),stop=document.getElementById('stopReadAloud');if(play){let label=play.querySelector('.player-label');if(label)label.textContent=narrationState==='playing'?'Pause aloud':narrationState==='paused'?'Resume aloud':'Play aloud';play.setAttribute('aria-label',narrationState==='playing'?'Pause lesson narration':narrationState==='paused'?'Resume lesson narration':'Play lesson narration');play.setAttribute('aria-pressed',String(narrationState==='playing'));let icon=play.querySelector('[aria-hidden]');if(icon)icon.textContent=narrationState==='playing'?'Ⅱ':'▶'}if(stop)stop.disabled=narrationState==='idle'}
function stopReadAloud(showMessage=false){if('speechSynthesis'in window)speechSynthesis.cancel();activeUtterance=null;narrationState='idle';updateNarrationControls();if(showMessage)toast('Read aloud stopped')}
function speakLesson(){if(!('speechSynthesis'in window)){toast('Read aloud is not available in this browser.');return}if(narrationState==='playing'){speechSynthesis.pause();narrationState='paused';updateNarrationControls();toast('Read aloud paused');return}if(narrationState==='paused'){speechSynthesis.resume();narrationState='playing';updateNarrationControls();toast('Read aloud resumed');return}let content=document.getElementById('lessonNarration');if(!content){toast('Open a lesson to use read aloud.');return}speechSynthesis.cancel();activeUtterance=new SpeechSynthesisUtterance(content.innerText);let lesson=lessons.find(item=>item.id===view.split(':')[1]);activeUtterance.lang=({English:'en-US','Yorùbá':'yo-NG',Kiswahili:'sw-KE',Français:'fr-FR'})[lesson?.lang||state.language]||'en-US';let utterance=activeUtterance;utterance.onend=()=>{if(activeUtterance===utterance){activeUtterance=null;narrationState='idle';updateNarrationControls()}};utterance.onerror=()=>{if(activeUtterance===utterance){activeUtterance=null;narrationState='idle';updateNarrationControls();toast('Read aloud could not continue. Try again.')}};narrationState='playing';updateNarrationControls();speechSynthesis.speak(utterance);toast('Reading lesson aloud')}
function downloadReport(){let rows=['InclusiveLearn Africa - Learning Progress Report','Student,Lesson,Progress',...lessons.map(l=>`${state.name},${l.title},${state.progress[l.id]??l.progress}%`)];let blob=new Blob([rows.join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='inclusivelearn-progress-report.csv';a.click();URL.revokeObjectURL(a.href);toast('Your report has downloaded')}
function modal(title,body,action,callback){let back=document.createElement('div');back.className='modalback';back.innerHTML=`<div class="modal"><div class="eyebrow">INCLUSIVELEARN</div><h2>${title}</h2><p>${body}</p><div class="field"><label>Assignment or review note</label><input placeholder="Add a title or note"></div><div class="toolbar" style="justify-content:flex-end"><button class="btn light" data-close>Cancel</button><button class="btn" data-confirm>${action}</button></div></div>`;document.body.append(back);addSpeechInputControls(back);back.querySelector('[data-close]').onclick=()=>back.remove();back.querySelector('[data-confirm]').onclick=()=>{back.remove();callback()};back.onclick=e=>{if(e.target===back)back.remove()}}
function createAssignment(){modal('Create a classroom assignment','Choose a learning activity and share it with your students.','Assign to class',()=>toast('Assignment shared with your learners ✓'))}
function login(){
 const signup=authMode==='signup';
 return `<div class="loginpage"><section class="loginvisual"><div class="brand" style="padding:0;color:white"><span class="brandmark">✿</span><span>InclusiveLearn<small style="color:#c3e7d3">AFRICA · LEARN TOGETHER</small></span></div><div class="loginstory"><div class="eyebrow" style="color:#bdebd2">LEARNING WITHOUT BARRIERS</div><h1>Every learner belongs. Every learner can grow.</h1><p>An inclusive learning space for African classrooms and families. Learn at your own pace, with tools that adapt to you.</p><div class="auth-proof"><span>Accessible by design</span><span>Works offline</span><span>Made for community</span></div></div><small class="visual-footer">INCLUSIVE LEARNING · SHARED PROGRESS</small></section><section class="loginform"><div class="brand" style="padding:0"><span class="brandmark">✿</span><span>InclusiveLearn<small>AFRICA · LEARN TOGETHER</small></span></div><div class="auth-heading"><span class="eyebrow">${signup?'GET STARTED':'YOUR LEARNING SPACE'}</span><h2>${signup?'Create your account':'Welcome back'}</h2><p>${signup?'Join your classroom and start learning your way.':'Sign in to continue your learning journey.'}</p></div><div class="rolecards">${[['Student','🧒'],['Educator','👩🏾‍🏫'],['Parent','👨‍👧'],['Admin','🛠️']].map(([r,i])=>`<button type="button" class="rolecard ${state.role===r?'selected':''}" data-loginrole="${r}"><span>${i}</span>${r}</button>`).join('')}</div><form id="authForm" novalidate>${signup?`<div class="field"><label for="fullName">Full name</label><input id="fullName" name="name" autocomplete="name" placeholder="Your name" required minlength="2"></div>`:''}<div class="field"><label for="email">Email or phone number</label><input id="email" name="email" value="${esc(state.email||'')}" placeholder="you@example.com" autocomplete="username" required></div><div class="field"><label for="password">Password</label><input id="password" name="password" placeholder="${signup?'Create a password':'Enter your password'}" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="4"><small class="field-hint">${signup?'Use at least 4 characters.':'Enter your password to continue.'}</small></div><p class="auth-error" id="authError" role="alert"></p><button class="btn auth-submit" id="authSubmit" type="submit">${signup?'Create account':'Sign in'} <span aria-hidden="true">→</span></button></form><div class="auth-switch">${signup?'Already have an account?':'New to InclusiveLearn?'} <button class="textbtn" id="toggleAuth" type="button">${signup?'Sign in':'Create an account'}</button></div><button class="demo-link" id="explore" type="button">Explore as a learner <span>→</span></button><div class="notice auth-note"><span>🔐</span><span>Your learning space is saved in this browser.</span></div><section class="project-overview" aria-labelledby="projectOverviewTitle"><div class="eyebrow">THE PROJECT</div><h2 id="projectOverviewTitle">Why InclusiveLearn exists</h2><div class="project-grid"><article class="project-item"><span class="project-number">01</span><div><h3>Problem statement</h3><p>Many learners, especially learners with disabilities, face digital lessons they cannot access, limited local-language resources, and unreliable internet that interrupts learning.</p></div></article><article class="project-item"><span class="project-number">02</span><div><h3>Why it is a problem</h3><p>These barriers reduce participation and independence, make it harder for educators to support different needs, and leave families without a clear way to follow learning progress.</p></div></article><article class="project-item"><span class="project-number">03</span><div><h3>Proposed solution</h3><p>InclusiveLearn brings accessible lessons, assistive settings, offline learning, educator-reviewed content, progress tracking, and direct family communication into one role-based learning website.</p></div></article></div></section></section></div>`
}
function recipientIdValid(id){return Boolean(id&&contacts.some(contact=>contact.id===id))}
function personName(role){return contacts.find(contact=>contact.role===role)?.name||state.roleNames?.[role]||({Student:'Learner',Educator:'Educator',Parent:'Family member',Admin:'Administrator'}[role]||'Contact')}
function inboxMessages(){let all=[...(remoteMessages||[]),...(platform.messages||[])],seen=new Set();return all.filter(message=>{let mine=state.accountId?(message.fromUserId===state.accountId||message.toUserId===state.accountId):message.fromRole===state.role||message.toRole===state.role;if(!mine&&message.fromRole!==state.role&&message.toRole!==state.role)return false;let key=message.id||`${message.fromUserId||message.from}:${message.toUserId||message.to}:${message.time}:${message.text}`;if(seen.has(key))return false;seen.add(key);return true}).sort((a,b)=>(Date.parse(b.time)||0)-(Date.parse(a.time)||0))}
function notifyRole(role,title,body,target='Messages',accountId=null){platform.notifications=platform.notifications||[];let notification={id:`local-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,role,accountId,title,body,target,read:false,time:new Date().toLocaleString()};platform.notifications.unshift(notification);persist();return notification}
async function sendToRole(role,text,kind='message',recipientId=''){let recipient=contacts.find(contact=>contact.id===recipientId&&contact.role===role);if(state.accountId){if(!recipient)throw new Error('Choose a valid person from your contacts before sending.');let response=await fetch('/api/messages',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({recipientId:recipient.id,recipientRole:role,text,kind})});let data;try{data=await response.json()}catch{throw new Error('The message service returned an unreadable response. Refresh the page and try again.')}if(!response.ok)throw new Error(data.error||'Your message could not be sent.');remoteMessages=[data.message,...(remoteMessages||[])];if(!platform.messages.some(item=>item.id===data.message.id))platform.messages.unshift(data.message);return data.message}let local={id:`guest-${Date.now()}`,from:state.name,fromRole:state.role,fromUserId:'',to:recipient?.name||personName(role),toRole:role,toUserId:recipientId,text,kind,time:new Date().toLocaleString()};platform.messages.unshift(local);notifyRole(role,kind==='family-update'?'Family learning update':`Message from ${state.name}`,text.slice(0,110),'Messages',recipientId||null);persist();return local}function notificationDropdown(){let items=(platform.notifications||[]).filter(n=>n.role===state.role&&(!n.accountId||n.accountId===state.accountId)).slice(0,8);let rows=items.map(n=>'<button class=\"notification-item\" data-notice=\"'+esc(n.id)+'\" data-view=\"'+esc(n.target||'Messages')+'\"><span class=\"notification-icon\">✉</span><span><b>'+esc(n.title||'Update')+'</b><small>'+esc(n.body||'')+' · '+esc(n.time||'')+'</small></span>'+(n.read?'':'<i></i>')+'</button>').join('');return '<div class=\"notification-panel\"><div class=\"notification-head\"><div><b>Notifications</b><small>'+items.filter(n=>!n.read).length+' unread updates</small></div><button class=\"textbtn\" id=\"markAllRead\">Mark all read</button></div>'+(rows||'<div class=\"notification-empty\">You’re all caught up.</div>')+'</div>'}function messagesPage(){let rows=inboxMessages();let recipients=contacts.filter(c=>c.role!==state.role&&c.role!=='Admin').map(c=>[c.role,c.name,c.id]);return `<div class="welcome"><div><div class="eyebrow">STAY CONNECTED</div><h1>Messages</h1><p>Choose a person, send a message, and follow the conversation in your inbox.</p></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Inbox & sent</h2><span class="chip green">${rows.length} messages</span></div><div class="conversation-list">${rows.length?rows.map(m=>{let incoming=m.toRole===state.role;return `<article class="message conversation"><div class="avatar">${initials(incoming?m.from:personName(m.toRole))}</div><div style="flex:1"><b>${incoming?'From':'To'} ${esc(incoming?m.from:`${m.to||personName(m.toRole)} · ${m.toRole}`)}</b><p>${esc(m.text)}</p><small>${esc(m.kind==='family-update'?'Family update · ':'')}${esc(m.time)}</small></div></article>`}).join(''):'<div class="empty-state"><b>Your inbox is ready</b><p>Messages from your learning community will appear here.</p></div>'}</div><form id="messageFormNew"><div class="field"><label for="messageRecipient">Send to</label><select id="messageRecipient" class="filter" required>${recipients.map(([r,n,id])=>`<option value="${r}|${id}">${esc(n)} · ${r}</option>`).join('')}</select></div><div class="field"><label for="messageTextNew">Message</label><textarea id="messageTextNew" rows="4" required maxlength="1200" placeholder="Write a thoughtful message..."></textarea></div><button class="btn">Send message →</button></form></div><div class="rightstack"><div class="card"><div class="sectionhead"><h2>Your contacts</h2><span class="chip">Learning community</span></div>${recipients.map(([r,n])=>`<div class="message"><div class="avatar">${initials(n)}</div><div><b>${esc(n)}</b><p>${r==='Educator'?'Class educator · replies during school hours':r==='Parent'?'Family contact':'Learner in your classroom'}</p></div></div>`).join('')}</div><div class="notice"><span>✦</span><span>Messages are delivered to the recipient’s inbox and notification centre.</span></div></div></div>`}
function contentCards(list){return list.map(c=>{let audio=safeMediaUrl(c.audioUrl),format=resourceFormat(c),canDelete=state.role==='Admin'||(state.role==='Educator'&&c.authorId===state.accountId);return `<article class="card course"><div class="coursebody"><span class="chip green">${esc(c.status||'Published')}</span><div class="eyebrow" style="margin-top:14px">${esc(c.subject)} · ${esc(c.grade)} · ${esc(c.lang||'English')} · ${esc(c.type||'Lesson')}</div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="content-preview"><b>Learning content</b><p>${esc(c.content)}</p>${c.objectives?`<p><b>Learning objectives:</b> ${esc(c.objectives)}</p>`:''}${c.activity?`<p><b>Activity:</b> ${esc(c.activity)}</p>`:''}${c.assessment?`<p><b>Success criteria:</b> ${esc(c.assessment)}</p>`:''}${audio?`<div class="media-resource"><b>Audio lesson</b><audio controls preload="none" src="${esc(audio)}">Your browser does not support audio playback.</audio></div>`:''}${c.videoUrl?videoPlayer(c.videoUrl,'Video lesson'):''}</div><div class="resource-actions"><span class="chip">${esc(format)} resource</span>${c.type==='Assignment'||c.type==='Project'?`<button type="button" class="btn small" data-open-assignment="task-${esc(c.id)}">Open assignment</button>`:''}<button type="button" class="textbtn" data-save-content="${esc(c.id)}">${state.savedResources?.[c.id]?'✓ Saved offline':'↓ Save offline'}</button>${canDelete?`<button type="button" class="btn small danger" data-delete-content="${esc(c.id)}">Delete published content</button>`:''}</div><small>Created by ${esc(c.author||'Educator')}</small></div></article>`}).join('')}
function catalog(){let custom=platform.published,all=[...lessons,...custom],grades=[...new Set(all.map(item=>item.grade).filter(Boolean))],list=all.filter(l=>(filter==='All subjects'||l.subject===filter)&&l.title.toLowerCase().includes(query.toLowerCase())&&(catalogGrade==='All grades'||l.grade===catalogGrade)&&(catalogLanguage==='All languages'||(l.lang||l.language||'English')===catalogLanguage)&&(catalogFormat==='All formats'||resourceFormat(l)===catalogFormat));return `<div class="welcome"><div><div class="eyebrow">${state.role==='Educator'?'CLASSROOM CONTENT':'YOUR LEARNING SPACE'}</div><h1>${state.role==='Educator'?'Content library':'My learning'}</h1><p>${state.role==='Educator'?'Explore published materials and create accessible classroom resources.':'Browse lessons by subject, grade, language, or media type.'}</p></div>${state.role==='Educator'?'<button class="btn" id="newContent">＋ Create content</button>':'<span class="chip green">Admin approved content</span>'}</div><div class="toolbar catalog-filters"><input id="search" class="search" placeholder="Search lessons..." value="${esc(query)}" aria-label="Search lessons"><select id="subjectfilter" class="filter" aria-label="Filter by subject">${['All subjects',...new Set(all.map(x=>x.subject))].map(x=>`<option ${filter===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="gradeFilter" class="filter" aria-label="Filter by grade"><option>All grades</option>${grades.map(x=>`<option ${catalogGrade===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="languageFilter" class="filter" aria-label="Filter by language"><option>All languages</option>${['English','Yorùbá','Kiswahili','Français'].map(x=>`<option ${catalogLanguage===x?'selected':''}>${x}</option>`).join('')}</select><select id="formatFilter" class="filter" aria-label="Filter by media type"><option>All formats</option>${['Text','Audio','Video'].map(x=>`<option ${catalogFormat===x?'selected':''}>${x}</option>`).join('')}</select><span class="chip">${list.length} materials</span></div><div class="grid catalog">${list.length?list.map(item=>custom.some(c=>c.id===item.id)?contentCards([item]):courseCard(item)).join(''):'<div class="card empty-state"><h3>No materials match these filters</h3><p>Try another subject, grade, language, or format.</p></div>'}</div>`}
function educatorPage(){let pending=platform.submissions.filter(s=>s.status==='Pending').length,updates=platform.messages.filter(m=>m.toRole==='Educator').length;return `<div class="welcome"><div><div class="eyebrow">EDUCATOR SPACE · GRADE 5</div><h1>Your classroom, ${esc(state.name)}</h1><p>Create accessible learning materials, follow family conversations, and support every learner.</p></div><button class="btn" id="newContent">＋ Create learning content</button></div><div class="grid stats"><div class="card stat"><div><div><div class="label">Learners connected</div><div class="value">${classroomRoster.length}</div><div class="hint">Across your classroom</div></div></div><div class="staticon">♙</div></div><div class="card stat"><div><div class="label">Published content</div><div class="value">${platform.published.length}</div><div class="hint">Available to learners</div></div><div class="staticon">▤</div></div><div class="card stat"><div><div class="label">Awaiting admin review</div><div class="value">${pending}</div><div class="hint">Submission queue</div></div><div class="staticon">◷</div></div><div class="card stat"><div><div class="label">Family / learner messages</div><div class="value">${updates}</div><div class="hint">Open your inbox</div></div><div class="staticon">✉</div></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Content workflow</h2><button class="textbtn" data-view="Content library">Open library →</button></div><p class="muted-copy">Create a complete lesson or assignment with objectives, teaching content, activities, and an assessment. Submit it for administrator review. Approved items are published to student learning spaces.</p><div class="settingrow"><div><b>In review</b><p>${pending} submission${pending===1?'':'s'} awaiting a decision</p></div><span class="chip gold">${pending} pending</span></div><div class="settingrow"><div><b>Published</b><p>${platform.published.length} approved item${platform.published.length===1?'':'s'} visible to students</p></div><span class="chip green">Live to learners</span></div>${platform.submissions.filter(s=>s.author===state.name).slice().reverse().map(s=>`<div class="settingrow"><div style="flex:1"><b>${esc(s.title)}</b><p>${esc(s.type)} · ${esc(s.createdAt)}${s.reviewNote?` · ${esc(s.reviewNote)}`:""}</p></div><span class="chip ${s.status==="Approved"?"green":s.status==="Pending"?"gold":"red"}">${esc(s.status)}</span></div>`).join("")}<button class="btn" id="newContent">Create a lesson or assignment →</button></div><div class="rightstack"><div class="card"><div class="sectionhead"><h2>Family communication</h2><span class="chip">Connected</span></div><p class="muted-copy">Send a meaningful learning update directly to a family member’s dashboard and notification centre.</p><button class="btn soft" id="sendFamilyUpdate">Send update to family</button><button class="btn light" style="width:100%;margin-top:8px" data-view="Messages">Open messages (${updates})</button></div><div class="card"><h2>Classroom tools</h2><button class="btn light" style="width:100%;margin-top:8px" data-view="Reports">View class reports</button></div></div></div>`}
function parentPage(){let incoming=inboxMessages().filter(message=>message.toRole==='Parent').length,child=parentChild,progress=child?.progress||{},completed=Object.values(progress).filter(value=>Number(value)>=100).length,average=Object.keys(progress).length?Math.round(Object.values(progress).reduce((sum,value)=>sum+Number(value),0)/Object.keys(progress).length):0;return `<div class="welcome"><div><div class="eyebrow">FAMILY SPACE</div><h1>${child?`Learning with ${esc(child.name)}`:`Hello, ${esc(state.name.split(' ')[0])}`}</h1><p>${child?'Follow learning progress and stay connected with the educator.':'Ask your learner to add your email or phone under Settings to share their progress.'}</p></div><button class="btn" data-view="Messages">✉ Message educator</button></div><div class="grid stats"><div class="card stat"><div><div class="label">Completed lessons</div><div class="value">${completed}</div><div class="hint">From the learner’s saved progress</div></div><div class="staticon">▤</div></div><div class="card stat"><div><div class="label">Average lesson progress</div><div class="value">${average}%</div><div class="hint">Across started lessons</div></div><div class="staticon">↗</div></div><div class="card stat"><div><div class="label">Saved for offline</div><div class="value">${child?.saved?.length||0}</div><div class="hint">Available on learner’s device</div></div><div class="staticon">↓</div></div><div class="card stat"><div><div class="label">Educator messages</div><div class="value">${incoming}</div><div class="hint">Delivered to this inbox</div></div><div class="staticon">✉</div></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>${child?`${esc(child.name)}’s learning`:'Learner connection'}</h2><button class="textbtn" data-view="Child progress">Full report →</button></div>${child?lessons.map(lesson=>{let value=Number(progress[lesson.id]||0);return `<div class="settingrow"><span class="lessonart" style="width:43px;height:43px;flex:0 0 43px">${lesson.icon}</span><div style="flex:1"><b>${esc(lesson.title)}</b><p>${esc(lesson.subject)} · ${esc(lesson.grade)} · ${esc(lesson.lang||'English')}</p><div class="progress"><i style="width:${value}%"></i></div></div><strong>${value}%</strong></div>`}).join(''):'<div class="empty-state"><b>No learner linked yet</b><p>After the learner adds this account’s email or phone in Settings, their progress will appear here.</p></div>'}</div><div class="rightstack"><div class="card"><h2>Talk to the educator</h2><p class="muted-copy">Your message goes to the educator inbox and notification centre.</p><button class="btn" data-view="Messages">Write a message →</button></div><div class="card"><h2>Latest educator updates</h2>${inboxMessages().filter(message=>message.toRole==='Parent').slice(0,3).map(message=>`<div class="message"><div class="avatar">${initials(message.from)}</div><div><b>${esc(message.from)}</b><p>${esc(message.text)}</p><small>${esc(message.time)}</small></div></div>`).join('')||'<p class="muted-copy">Messages from the educator will appear here.</p>'}</div></div></div>`}
function parentProgressPage(){let child=parentChild;if(!child)return `<div class="welcome"><div><div class="eyebrow">FAMILY PROGRESS</div><h1>Learning report</h1><p>Link a learner account to see their module progress and offline materials.</p></div><button class="btn" data-view="Settings">Open settings →</button></div><div class="card empty-state"><h2>No learner account linked</h2><p>The learner can add your email or phone number in their profile settings to share their progress with you.</p></div>`;let rows=lessons.map(lesson=>({lesson,value:Number(child.progress?.[lesson.id]||0)}));return `<div class="welcome"><div><div class="eyebrow">FAMILY PROGRESS · ${esc(child.name)}</div><h1>Learning report</h1><p>Progress saved on the learner’s account${child.updatedAt?` · Synced ${new Date(child.updatedAt).toLocaleString()}`:''}.</p></div><button class="btn light" id="downloadReport">↓ Download report</button></div><div class="card"><div class="sectionhead"><h2>Module progress</h2><span class="chip">${rows.filter(row=>row.value>=100).length} completed</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Lesson</th><th>Subject</th><th>Progress</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.lesson.title)}</td><td>${esc(row.lesson.subject)}</td><td><div class="progress" style="width:140px"><i style="width:${row.value}%"></i></div><small>${row.value}%</small></td></tr>`).join('')}</tbody></table></div></div>`}
function adminPage(){let pending=platform.submissions.filter(s=>s.status==='Pending').length;return `<div class="welcome"><div><div class="eyebrow">PLATFORM ADMINISTRATION</div><h1>Platform operations</h1><p>Review classroom content, monitor communication, and maintain a safe learning library.</p></div><button class="btn light" id="exportData">↓ Export platform report</button></div><div class="grid stats"><div class="card stat"><div><div class="label">Registered roles</div><div class="value">4</div><div class="hint">Learners, educators, families, admins</div></div><div class="staticon">♙</div></div><div class="card stat"><div><div class="label">Published content</div><div class="value">${platform.published.length}</div><div class="hint">Approved and student-visible</div></div><div class="staticon">▤</div></div><div class="card stat"><div><div class="label">Needs review</div><div class="value">${pending}</div><div class="hint">Educator submissions</div></div><div class="staticon">◷</div></div><div class="card stat"><div><div class="label">Messages delivered</div><div class="value">${platform.messages.length}</div><div class="hint">Role-to-role communication</div></div><div class="staticon">✉</div></div></div><div class="grid cols"><div class="card"><div class="sectionhead"><h2>Review queue</h2><button class="textbtn" data-view="Content review">Open all →</button></div>${pending?platform.submissions.filter(s=>s.status==='Pending').slice(0,5).map(s=>`<div class="settingrow"><div style="flex:1"><b>${esc(s.title)}</b><p>${esc(s.author)} · ${esc(s.grade)} · ${esc(s.subject)}</p></div><button class="btn small" data-view="Content review">Review</button></div>`).join(''):'<div class="empty-state">No items are awaiting review.</div>'}</div><div class="rightstack"><div class="card"><h2>Platform health</h2>${[['Learning content','Operational'],['Inbox notifications','Operational'],['Role spaces','Operational'],['Accessibility tools','Operational']].map(([a,b])=>`<div class="settingrow"><b>${a}</b><span class="chip green">${b}</span></div>`).join('')}</div><div class="card"><h2>Recent platform activity</h2>${platform.activity.slice(0,5).map(a=>`<div class="settingrow"><div><b>${esc(a.text)}</b><p>${esc(a.time)}</p></div></div>`).join('')||'<p class="muted-copy">New submissions, approvals, and messages will be listed here.</p>'}</div></div></div>`}
function adminReviewPage(){let submissions=platform.submissions;return `<div class="welcome"><div><div class="eyebrow">ADMIN · CONTENT SAFETY</div><h1>Content review</h1><p>Review complete educator lessons and assignments before publishing.</p></div><span class="chip gold">${submissions.filter(s=>s.status==='Pending').length} awaiting review</span></div><div class="grid review-list">${submissions.length?submissions.slice().reverse().map(s=>`<article class="card review-card"><div class="sectionhead"><div><span class="chip ${s.status==='Pending'?'gold':s.status==='Approved'?'green':'red'}">${esc(s.status)}</span><span class="chip">${esc(s.type)}</span></div><small>${esc(s.createdAt)}</small></div><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p><div class="review-meta">${esc(s.subject)} · ${esc(s.grade)} · ${esc(s.duration)} · Submitted by ${esc(s.author)}</div><div class="review-section"><b>Learning objectives</b><p>${esc(s.objectives)}</p><b>Teaching content</b><p>${esc(s.content)}</p><b>Activity</b><p>${esc(s.activity)}</p><b>Assessment</b><p>${esc(s.assessment)}</p>${s.audioUrl?`<div class="media-resource"><b>Audio preview</b><audio controls preload="none" src="${esc(safeMediaUrl(s.audioUrl))}"></audio></div>`:''}${s.videoUrl?videoPlayer(s.videoUrl,'Video preview'):''}</div>${s.status==='Pending'?`<div class="review-actions"><button class="btn" data-review="${esc(s.id)}" data-decision="approve">Approve & publish to students</button><button class="btn danger" data-review="${esc(s.id)}" data-decision="reject">Reject submission</button></div>`:`<p class="review-meta">${s.status==='Approved'?'Published to student dashboards.':s.status==='Removed'?'Removed from student dashboards.':'Returned to educator.'}${s.reviewNote?` Review note: ${esc(s.reviewNote)}`:''}</p>`}</article>`).join(''):'<div class="card empty-state"><h2>Review queue is clear</h2><p>New educator content will appear here for approval.</p></div>'}</div><section class="card published-manager"><div class="sectionhead"><div><h2>Published learning materials</h2><small>Remove an item here to take it out of student learning spaces.</small></div><span class="chip green">${platform.published.length} live</span></div>${platform.published.length?`<div class="grid catalog">${contentCards(platform.published)}</div>`:'<div class="empty-state"><b>No published content</b><p>Approved educator resources will appear here.</p></div>'}</section>`}
function pageForRole(){const allowed=roleNavigation().map(([label])=>label);if(view.startsWith('Lesson:'))return state.role==='Student'?lessonPage(view.split(':')[1]):(view='Home',pageForRole());if(!allowed.includes(view))view='Home';if(view==='Settings')return settingsPage();if(view==='Messages')return messagesPage();if(state.role==='Student'){if(view==='My learning')return catalog();if(view==='Offline library')return offlinePage();if(view==='Progress')return progressPage();return studentHome()}if(state.role==='Educator'){if(view==='Content library')return catalog();if(view==='Reports')return educatorReportsPage();return educatorPage()}if(state.role==='Parent')return view==='Child progress'?parentProgressPage():parentPage();if(state.role==='Admin'){if(view==='Content review')return adminReviewPage();if(view==='Usage reports')return adminUsagePage();return adminPage()}return studentHome()}
function createAssignment(){let back=document.createElement('div');back.className='modalback';back.innerHTML=`<form class="modal content-modal" id="contentForm"><div class="eyebrow">EDUCATOR CONTENT STUDIO</div><h2>Create a complete learning resource</h2><p>Build a lesson or assignment. Admin approval publishes it to students.</p><div class="form-grid"><div class="field"><label>Title</label><input name="title" required maxlength="90" placeholder="e.g. Exploring our local wetlands"></div><div class="field"><label>Resource type</label><select name="type" class="filter"><option>Lesson</option><option>Assignment</option><option>Project</option></select></div><div class="field"><label>Subject</label><select name="subject" class="filter">${['Science','Mathematics','Reading','Life Skills','Social Studies','Arts'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Grade / level</label><input name="grade" required placeholder="Grade 5"></div><div class="field"><label>Estimated time</label><input name="duration" required placeholder="30 minutes"></div><div class="field"><label>Due date (assignments)</label><input type="date" name="dueDate"></div><div class="field"><label>Content language</label><select name="lang" class="filter">${['English','Yorùbá','Kiswahili','Français'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>Short description</label><textarea name="description" rows="2" required placeholder="What will learners explore?"></textarea></div><div class="field full"><label>Learning objectives</label><textarea name="objectives" rows="2" required placeholder="By the end, learners will be able to..."></textarea></div><div class="field full"><label>Teaching content / instructions</label><textarea name="content" rows="5" required placeholder="Write the full lesson explanation or assignment brief..."></textarea></div><div class="field full"><label>Learning activity</label><textarea name="activity" rows="3" required placeholder="Steps, materials, and learner task"></textarea></div><div class="field full"><label>Assessment / success criteria</label><textarea name="assessment" rows="3" required placeholder="How will learners show what they learned?"></textarea></div><div class="field"><label>Audio file URL (optional)</label><input type="url" name="audioUrl" placeholder="Direct link to an MP3 or audio file"></div><div class="field"><label>Video URL (optional)</label><input type="url" name="videoUrl" placeholder="MP4, WebM, YouTube, or Vimeo link"><small class="field-hint">Students will get an in-lesson video player after approval.</small></div><div class="field full"><label>Accessibility supports (optional)</label><textarea name="accessibility" rows="2" placeholder="Plain language, audio option, large print, local examples..."></textarea></div></div><div class="modal-actions"><button type="button" class="btn light" data-close>Save later / cancel</button><button type="submit" class="btn">Submit for admin review →</button></div></form>`;document.body.append(back);addSpeechInputControls(back);back.querySelector('[data-close]').onclick=()=>back.remove();back.onclick=e=>{if(e.target===back)back.remove()};back.querySelector('#contentForm').onsubmit=async e=>{e.preventDefault();let form=e.currentTarget,submit=form.querySelector('button[type="submit"]'),data=Object.fromEntries(new FormData(form).entries());if(submit)submit.disabled=true;try{let response=await fetch('/api/content/submissions',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify(data)}),result;try{result=await response.json()}catch{throw new Error('The server returned an unreadable response. Please try again.')}if(!response.ok)throw new Error(result.error||'Your lesson could not be submitted.');platform.submissions=platform.submissions||[];platform.submissions.unshift(result.submission);platform.activity=platform.activity||[];platform.activity.unshift({text:`${state.name} submitted “${result.submission.title}” for admin review`,time:result.submission.createdAt});persist();back.remove();await refreshPlatform();app();toast('Lesson submitted. It is now in the admin review queue.')}catch(error){if(submit)submit.disabled=false;toast(error.message||'Could not submit the lesson. Check your connection and try again.')}};;}
async function parseAuthResponse(response){try{return await response.json()}catch{throw new Error('This page is not connected to the InclusiveLearn server. Run npm run dev from the project folder and open the localhost address shown in the terminal.')}}
function bindAuth(){document.querySelectorAll('[data-loginrole]').forEach(b=>b.onclick=()=>{state.role=b.dataset.loginrole;app()});let form=document.getElementById('authForm');if(form)form.onsubmit=e=>{e.preventDefault();let email=document.getElementById('email'),password=document.getElementById('password'),name=document.getElementById('fullName'),error=document.getElementById('authError');let message=!email.value.trim()?'Enter your email address or phone number.':password.value.length<4?'Your password must have at least 4 characters.':authMode==='signup'&&(!name.value.trim()||name.value.trim().length<2)?'Enter your name to create your account.':'';if(message){if(error)error.textContent=message;return}state.email=email.value.trim();state.name=authMode==='signup'?name.value.trim():(state.roleNames?.[state.role]||roleDisplay[state.role]);if(authMode==='signup'){platform.names=platform.names||{};platform.names[state.role]=state.name}state.loggedIn=true;authMode='signin';view='Home';persist();app();toast('Welcome to your learning space')};document.getElementById('explore')?.addEventListener('click',()=>{state.role='Student';state.name=roleDisplay.Student;state.email=roleEmails.Student;state.loggedIn=true;persist();app()});document.getElementById('toggleAuth')?.addEventListener('click',()=>{authMode=authMode==='signup'?'signin':'signup';app()})}
function bindWorkflow(){document.getElementById('signoutSide')?.addEventListener('click',logoutAccount);document.getElementById('notificationButton')?.addEventListener('click',()=>{notificationsOpen=!notificationsOpen;app()});document.querySelectorAll('[data-open-assignment]').forEach(button=>button.addEventListener('click',()=>openAssignment(button.dataset.openAssignment)));document.getElementById('gradeFilter')?.addEventListener('change',e=>{catalogGrade=e.target.value;app()});document.getElementById('languageFilter')?.addEventListener('change',e=>{catalogLanguage=e.target.value;app()});document.getElementById('formatFilter')?.addEventListener('change',e=>{catalogFormat=e.target.value;app()});document.querySelectorAll('[data-save-lesson]').forEach(button=>button.addEventListener('click',()=>saveLessonOffline(button.dataset.saveLesson)));document.querySelectorAll('[data-save-content]').forEach(button=>button.addEventListener('click',async()=>{let item=platform.published.find(resource=>resource.id===button.dataset.saveContent);if(!item)return;state.savedResources=state.savedResources||{};state.savedResources[item.id]=item;cacheResourceMedia(item);if(!state.saved.includes(item.id))state.saved.push(item.id);persist();app();toast('Learning material saved for offline use')}));document.getElementById('messageFormNew')?.addEventListener('submit',async e=>{e.preventDefault();let text=document.getElementById('messageTextNew').value.trim(),recipientField=document.getElementById('messageRecipient'),[target,targetId]=(recipientField?.value||'').split('|');if(!text)return;if(!target||!recipientIdValid(targetId)){toast('Choose an available contact before sending.');return}let submit=e.currentTarget.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{await sendToRole(target,text,'message',targetId);await refreshSharedData();view='Messages';app();toast(`Message sent to ${contacts.find(c=>c.id===targetId)?.name||personName(target)}`)}catch(error){if(submit)submit.disabled=false;toast(error.message||'Your message could not be sent.')}});document.querySelectorAll('#newContent,#assignBtn,#assignBtn2').forEach(b=>b.addEventListener('click',createAssignment));document.getElementById('sendFamilyUpdate')?.addEventListener('click',()=>{let back=document.createElement('div');back.className='modalback';back.innerHTML=`<form class="modal" id="familyForm"><div class="eyebrow">FAMILY COMMUNICATION</div><h2>Send a learning update</h2><p>This update will appear on Sam Yusuf’s family dashboard and notification centre.</p><div class="field"><label>Update type</label><select name="kind" class="filter"><option>Weekly learning summary</option><option>Celebration</option><option>Learning support</option></select></div><div class="field"><label>Send to family member</label><select class="filter" name="recipientId" required>${contacts.filter(c=>c.role==="Parent").map(c=>`<option value="${c.id}">${c.name} · Parent</option>`).join("")||'<option value="">No parent account is linked yet</option>'}</select></div><div class="field"><label>Personal message</label><textarea name="text" required rows="5" maxlength="1200" placeholder="Share a specific achievement, what Amina worked on, and one supportive next step..."></textarea></div><div class="modal-actions"><button type="button" class="btn light" data-close>Cancel</button><button class="btn">Send to family →</button></div></form>`;document.body.append(back);addSpeechInputControls(back);back.querySelector('[data-close]').onclick=()=>back.remove();back.querySelector('#familyForm').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget).entries());let select=e.currentTarget.querySelector('[name=recipientId]'),recipientId=select?.value||'';if(state.accountId&&!recipientId){toast('Create a family account and link it from the learner profile first.');return}try{await sendToRole('Parent',`${d.kind}: ${d.text}`,'family-update',recipientId);back.remove();await refreshSharedData();app();toast('Learning update delivered to the family dashboard')}catch(error){toast(error.message||'The family update could not be sent.')}};});document.querySelectorAll('[data-review]').forEach(button=>button.addEventListener('click',async()=>{let id=button.dataset.review,decision=button.dataset.decision==='approve'?'Approved':'Rejected',item=platform.submissions.find(entry=>entry.id===id);if(!item)return;let buttons=[...document.querySelectorAll(`[data-review="${CSS.escape(id)}"]`)];buttons.forEach(control=>control.disabled=true);try{let response=await fetch(`/api/content/submissions/${encodeURIComponent(id)}/review`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({decision})}),result;try{result=await response.json()}catch{throw new Error('The server returned an unreadable response. Refresh and try again.')}if(!response.ok)throw new Error(result.error||'The review decision could not be saved.');await refreshPlatform();app();toast(decision==='Approved'?'Approved and published to student dashboards.':'Submission rejected; the educator has been notified.')}catch(error){buttons.forEach(control=>control.disabled=false);toast(error.message||'Could not save the review decision.')}}));}
function openAssignment(id){let task=(platform.assignments||[]).find(item=>item.id===id),resource=platform.published.find(item=>item.id===task?.contentId);if(!task||!resource)return;let completed=(task.completedBy||[]).includes(state.accountId||state.email);let back=document.createElement('div');back.className='modalback';back.innerHTML=`<form class="modal content-modal" id="studentAssignmentForm"><div class="eyebrow">CLASSROOM ASSIGNMENT</div><h2>${esc(resource.title)}</h2><p>${esc(resource.description)}</p><div class="review-section"><b>Learning content</b><p>${esc(resource.content)}</p><b>Your activity</b><p>${esc(resource.activity)}</p><b>Success criteria</b><p>${esc(resource.assessment)}</p>${resource.videoUrl?videoPlayer(resource.videoUrl,'Video lesson'):''}</div>${task.dueDate?`<p class="assignment-due">Due ${esc(task.dueDate)}</p>`:''}<div class="field"><label for="assignmentResponse">Your response</label><textarea id="assignmentResponse" rows="5" required ${completed?'disabled':''} placeholder="Write or dictate what you learned…"></textarea></div><div class="modal-actions"><button type="button" class="btn light" data-close>Close</button>${completed?'<span class="chip green">Submitted</span>':'<button type="submit" class="btn">Submit assignment →</button>'}</div></form>`;document.body.append(back);addSpeechInputControls(back);back.querySelector('[data-close]').onclick=()=>back.remove();back.querySelector('#studentAssignmentForm')?.addEventListener('submit',async e=>{e.preventDefault();let response=document.getElementById('assignmentResponse').value.trim();if(!response)return;task.completedBy=task.completedBy||[];task.completedBy.push(state.accountId||state.email);platform.assignmentResponses=platform.assignmentResponses||[];platform.assignmentResponses.unshift({taskId:task.id,contentId:resource.id,student:state.name,studentId:state.accountId||state.email,response,submittedAt:stamp()});state.progress[resource.id]=100;notifyRole('Educator',`Assignment submitted: ${resource.title}`,`${state.name} submitted their work.`,'Classroom');persist();await syncPlatform();back.remove();app();toast('Assignment submitted to your educator')})}
function studentHome(){let published=platform.published,tasks=(platform.assignments||[]).filter(task=>!(task.completedBy||[]).includes(state.accountId||state.email));return studentHomeBase()+(tasks.length?`<section class="card assignment-list"><div class="sectionhead"><div><span class="eyebrow">YOUR CLASSWORK</span><h2>Assignments to complete</h2></div><span class="chip gold">${tasks.length} open</span></div>${tasks.map(task=>`<div class="settingrow"><div style="flex:1"><b>${esc(task.title)}</b><p>${esc(task.grade)} · ${task.dueDate?`Due ${esc(task.dueDate)}`:'Assigned '+esc(task.assignedAt)}</p></div><button class="btn small" data-open-assignment="${esc(task.id)}">Open assignment →</button></div>`).join('')}</section>`:'')+(published.length?`<section class="card published-home"><div class="sectionhead"><div><span class="eyebrow">JUST APPROVED BY YOUR ADMIN</span><h2>New classroom learning</h2></div><span class="chip green">${published.length} new</span></div><div class="grid catalog">${contentCards(published)}</div></section>`:'')}
function app(){state.unread=platform.notifications.filter(n=>n.role===state.role&&(!n.accountId||n.accountId===state.accountId)&&!n.read).length;appBase()}
window.addEventListener('storage',e=>{if(e.key===PLATFORM_KEY){platform=JSON.parse(e.newValue||'{}');app()}});
