function translateUI(root){let dict=homeTranslations[state.language];document.documentElement.lang=({English:'en',Yorùbá:'yo',Kiswahili:'sw',Français:'fr'})[state.language]||'en';if(!dict)return;let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),node;while(node=walker.nextNode()){let before=node.nodeValue,trim=before.trim(),translated=dict[trim];if(!translated)for(let [source,target] of Object.entries(dict)){if(source.length>3&&trim.includes(source)){translated=trim.replaceAll(source,target);break}}if(translated)node.nodeValue=before.replace(trim,translated)}root.querySelectorAll('[placeholder]').forEach(el=>{let v=el.getAttribute('placeholder');if(dict[v])el.setAttribute('placeholder',dict[v])})}
function publicHome(){return `<div class="public-site"><header class="public-nav"><a class="public-brand" href="#home"><span class="brandmark">✿</span><span>InclusiveLearn<small>AFRICA · LEARN TOGETHER</small></span></a><nav aria-label="Main navigation"><a href="#problem">The challenge</a><a href="#solution">Our approach</a><a href="#features">Platform</a><a href="#faq">FAQ</a></nav><div class="public-actions"><select id="publicLanguage" class="public-language" aria-label="Choose interface language">${['English','Yorùbá','Kiswahili','Français'].map(x=>`<option ${state.language===x?'selected':''}>${x}</option>`).join('')}</select><button class="textbtn" data-open-auth="signin">Sign in</button><button class="btn small" data-open-auth="signup">Create account <span>↗</span></button></div><button class="mobile-menu" aria-label="Open menu" id="mobileMenu">☰</button></header><main id="home"><section class="landing-hero"><div class="hero-copy"><span class="eyebrow"><i></i> INCLUSIVE LEARNING · BUILT FOR EVERY COMMUNITY</span><h1>Learning should open doors for <em>every learner.</em></h1><p>Accessible lessons, thoughtful classroom tools, and stronger family connections—designed for the realities of learning across Africa.</p><div class="hero-actions"><button class="btn" data-open-auth="signup">Join your learning community <span>→</span></button><a class="hero-link" href="#problem">Explore the story <span>↓</span></a></div><div class="hero-proof"><span><b>01</b> Accessible by design</span><span><b>02</b> Ready for low connectivity</span><span><b>03</b> Connected to community</span></div></div><div class="hero-art" aria-label="Preview of the InclusiveLearn student dashboard"><div class="dashboard-preview"><div class="preview-top"><span class="preview-brand"><i></i> InclusiveLearn</span><span class="preview-greeting">Student space <b>AY</b></span></div><div class="preview-layout"><aside class="preview-rail"><i class="active"></i><i></i><i></i><i></i><i></i></aside><div class="preview-content"><small class="preview-date">MONDAY · 28 SEPTEMBER</small><h3>Good morning, Amina</h3><p>Your learning is moving forward.</p><div class="preview-metrics"><div><small>Lessons complete</small><b>08 <em>+2 this week</em></b></div><div><small>Learning streak</small><b>5 days</b></div></div><div class="preview-lesson"><div class="preview-lesson-art"><span></span><i></i></div><div class="preview-lesson-copy"><small>SCIENCE · GRADE 5</small><b>How plants grow</b><span>Continue learning <i>→</i></span><div class="preview-progress"><i></i></div></div></div><div class="preview-update"><span class="update-mark">✓</span><span><small>NEW FROM YOUR EDUCATOR</small><b>Wetland ecosystems project</b></span><span class="update-arrow">↗</span></div></div></div></div><div class="preview-float preview-approved"><span>✓</span><div><b>Reviewed and approved</b><small>Ready for students</small></div></div><div class="preview-float preview-family"><span>↗</span><div><b>Families in the loop</b><small>Updates delivered</small></div></div><div class="preview-orbit"></div></div></section><section class="trust-strip"><span>ONE LEARNING SPACE</span><b>Students</b><i></i><b>Educators</b><i></i><b>Families</b><i></i><b>Administrators</b></section><section class="story-section problem-section" id="problem"><div class="section-kicker">01 · THE CHALLENGE</div><div class="story-grid"><h2>Access to learning still depends on the learner’s circumstances.</h2><div><p class="story-lead">Many learners, especially learners with disabilities, encounter digital lessons that are difficult to use, too few resources in familiar languages, and internet access that can disappear without warning.</p><p>For families and educators, disconnected tools make it harder to see progress, coordinate support, and keep learning moving across home and school.</p></div></div><div class="problem-cards"><article><span class="line-icon">◉</span><h3>Materials that exclude</h3><p>Dense layouts and limited assistive options can make a lesson harder to reach than the learning itself.</p></article><article><span class="line-icon">⌁</span><h3>Connectivity that interrupts</h3><p>Unreliable internet can cut off lessons and progress at the moments learners need them.</p></article><article><span class="line-icon">⇄</span><h3>Support that gets disconnected</h3><p>When school and home tools do not connect, families can miss the context that helps a child thrive.</p></article></div></section><section class="impact-band" id="impact"><div class="impact-orb"></div><div class="section-kicker">02 · WHY IT MATTERS</div><div class="impact-content"><h2>When access is uneven, opportunity becomes uneven too.</h2><p>Learners can lose confidence and independence. Educators spend time working around tools instead of supporting individual needs. Families have fewer clear ways to celebrate progress or ask for help. Inclusive learning needs to work in the moments and places where learning actually happens.</p><div class="impact-points"><span>Participation</span><span>Independence</span><span>Continuity</span><span>Family partnership</span></div></div></section><section class="story-section solution-section" id="solution"><div class="section-kicker">03 · THE PROPOSED SOLUTION</div><div class="solution-heading"><h2>One thoughtful platform.<br><em>Support at every step.</em></h2><p>InclusiveLearn brings students, educators, families, and administrators into connected role-based spaces, with tools built around access, trust, and continuity.</p></div><div class="solution-flow"><article><span>01</span><h3>Learn accessibly</h3><p>Readable lessons, adaptable settings, and assistive tools support different ways of learning.</p></article><b class="flow-arrow">→</b><article><span>02</span><h3>Keep learning moving</h3><p>Save approved content for offline use and continue learning when connectivity is limited.</p></article><b class="flow-arrow">→</b><article><span>03</span><h3>Grow together</h3><p>Educators create content for review, students learn from approved resources, and families stay in the conversation.</p></article></div><button class="btn" data-open-auth="signup">Find your learning space <span>→</span></button></section><section class="feature-section" id="features"><div class="section-kicker">A CONNECTED LEARNING ECOSYSTEM</div><h2>Made for the whole learning community.</h2><div class="feature-grid"><article class="feature-card feature-student"><span class="feature-index">01 / STUDENT</span><div class="feature-symbol">↗</div><h3>Student learning</h3><p>Explore lessons, track progress, use accessibility tools, and keep saved content close.</p><span class="feature-chip">Learn at your pace</span></article><article class="feature-card feature-educator"><span class="feature-index">02 / EDUCATOR</span><div class="feature-symbol">▤</div><h3>Educator workspace</h3><p>Build complete lessons and assignments, follow class progress, and connect with families.</p><span class="feature-chip">Create · share · support</span></article><article class="feature-card feature-family"><span class="feature-index">03 / FAMILY</span><div class="feature-symbol">♡</div><h3>Family connection</h3><p>See a child’s progress, receive thoughtful updates, and message their educator directly.</p><span class="feature-chip">Stay in the loop</span></article><article class="feature-card feature-admin"><span class="feature-index">04 / ADMIN</span><div class="feature-symbol">✓</div><h3>Safe content review</h3><p>Review educator submissions and publish approved learning materials to students.</p><span class="feature-chip">Quality before publishing</span></article></div></section><section class="faq-section" id="faq"><div><div class="section-kicker">GOOD TO KNOW</div><h2>Frequently asked questions</h2><p>More about how InclusiveLearn supports learning communities.</p></div><div class="faq-list"><details><summary>Who is InclusiveLearn for?<span>＋</span></summary><p>Students, educators, families, and administrators each have a separate role-based workspace.</p></details><details><summary>Can learners use content without internet?<span>＋</span></summary><p>Lessons can be saved to the offline library so learners can revisit them when connectivity is limited.</p></details><details><summary>How does new educator content reach students?<span>＋</span></summary><p>Educators submit complete learning resources for admin review. When approved, the content is published to student dashboards.</p></details><details><summary>How do families stay connected?<span>＋</span></summary><p>Families can message educators and receive learning updates in their dashboard and notification centre.</p></details></div></section><section class="final-cta"><div class="cta-glow"></div><div><span class="section-kicker">YOUR NEXT STEP</span><h2>Make room for every learner.</h2><p>Join a learning community built to help everyone take part and move forward.</p></div><button class="btn cta-button" data-open-auth="signup">Create your account <span>→</span></button></section></main><footer class="public-footer"><a class="public-brand" href="#home"><span class="brandmark">✿</span><span>InclusiveLearn<small>AFRICA · LEARN TOGETHER</small></span></a><span>Accessible learning. Shared progress.</span><a href="#home">Back to top ↑</a></footer>${authOpen?`<div class="auth-overlay" id="authOverlay"><div class="auth-dialog"><button class="auth-close" id="closeAuth" aria-label="Close sign in">×</button>${login()}</div></div>`:''}</div>`}
function login(){let signup=authMode==='signup';return `<section class="auth-panel"><div class="auth-brand"><span class="brandmark">✿</span><div><b>InclusiveLearn</b><small>AFRICA · LEARN TOGETHER</small></div></div><div class="auth-heading"><span class="eyebrow">${signup?'GET STARTED':'YOUR LEARNING SPACE'}</span><h2>${signup?'Create your account':'Welcome back'}</h2><p>${signup?'Create a private account for your learning role.':'Sign in to your own learning space.'}</p></div><div class="rolecards">${(signup?[['Student','♙'],['Educator','▤'],['Parent','♡']]:[['Student','♙'],['Educator','▤'],['Parent','♡'],['Admin','⌘']]).map(([r,i])=>`<button type="button" class="rolecard ${state.role===r?'selected':''}" data-loginrole="${r}"><span>${i}</span>${r}</button>`).join('')}</div><form id="authForm" novalidate>${signup?`<div class="field"><label for="fullName">Full name</label><input id="fullName" name="name" autocomplete="name" placeholder="Your name" required minlength="2"></div>`:''}<div class="field"><label for="email">Email or phone number</label><input id="email" name="email" value="${esc(state.email||'')}" placeholder="you@example.com or +254..." autocomplete="username" required></div><div class="field"><label for="password">Password</label><input id="password" name="password" placeholder="${signup?'At least 8 characters':'Enter your password'}" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="8"><small class="field-hint">${signup?'Use at least 8 characters.':'Your account is private to this role.'}</small></div><p class="auth-error" id="authError" role="alert"></p><button class="btn auth-submit" id="authSubmit" type="submit">${signup?'Create account':'Sign in'} <span>→</span></button></form><div class="social-auth"><span>Or continue with</span><div><button type="button" class="social-button" data-provider="google"><b aria-hidden="true">G</b> Google</button><button type="button" class="social-button" data-provider="facebook"><b aria-hidden="true">f</b> Facebook</button></div></div><div class="auth-switch">${signup?'Already have an account?':'New to InclusiveLearn?'} <button class="textbtn" id="toggleAuth" type="button">${signup?'Sign in':'Create an account'}</button></div><button class="demo-link" id="explore" type="button">Explore as a learner <span>→</span></button></section>`}
function appBase(){let root=document.getElementById('app');document.documentElement.classList.toggle('large-text',state.font>100);document.documentElement.classList.toggle('high-contrast',state.contrast);if(!state.loggedIn){root.innerHTML=publicHome();iconify(root);translateUI(root);bindAuth();return}root.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home"><span class="brandmark">✿</span><span>InclusiveLearn<small>AFRICA · LEARN TOGETHER</small></span></a><div><div class="navlabel">${state.role.toUpperCase()} SPACE</div><nav class="nav">${roleNavigation().map(([t,i])=>`<button class="${view===t?'active':''}" data-view="${t}"><span class="ico">${i}</span>${t}</button>`).join('')}</nav><div class="role-space"><span class="role-space-mark">✿</span><span><small>YOUR SPACE</small><b>${esc(state.role)}</b></span></div></div><div class="sidebottom"><div class="helpbox"><b>Learning for everyone</b>Change text size, contrast or language anytime in Settings.</div><div class="profile"><div class="avatar">${initials()}</div><div style="flex:1"><b>${esc(state.name)}</b><small>${esc(state.role)} account</small></div><button class="textbtn" data-profile-signout aria-label="Sign out">↗</button></div></div></aside><main><header class="topbar"><div class="crumb"><a href="#dashboard" data-view="Home">InclusiveLearn</a><span>/</span><b>${esc(view)}</b></div><div class="topactions"><button class="pill ${state.offline||state.pendingSync||!navigator.onLine?'offline':'online'}" id="connect">${state.offline?'Offline · Sync pending':'Connected'}</button><select id="languageQuick" class="language-quick" aria-label="Choose language">${['English','Yorùbá','Kiswahili','Français'].map(x=>`<option ${state.language===x?'selected':''}>${x}</option>`).join('')}</select><button class="icon-button notification-trigger" id="notificationButton" aria-label="Notifications" aria-expanded="${notificationsOpen}">♧${state.unread>0?'<span class="notification-dot"></span>':''}</button><button type="button" class="avatar profile-trigger" id="profileButton" aria-label="Open profile" aria-expanded="${profileOpen}">${initials()}</button></div>${notificationsOpen?notificationDropdown():''}${profileOpen?`<div class="profile-panel"><div class="profile-panel-head"><div class="avatar">${initials()}</div><div><b>${esc(state.name)}</b><small>${esc(state.role)} · ${esc(state.email)}</small></div></div><button data-view="Settings">My profile & settings <span>→</span></button><button id="signout">Sign out <span>↗</span></button></div>`:''}</header><section class="page" id="dashboard">${pageForRole()}</section></main></div>`;iconify(root);translateUI(root);addSpeechInputControls(root);bindLegacy();bindShared()}
function app(){state.unread=platform.notifications.filter(n=>n.role===state.role&&!n.read).length;appBase()}
async function parseAuthResponse(response){try{return await response.json()}catch{throw new Error('This page is not connected to the InclusiveLearn server. Run npm run dev from the project folder and open the localhost address shown in the terminal.')}}
function bindAuth(){document.querySelectorAll('[data-open-auth]').forEach(button=>button.onclick=()=>{authMode=button.dataset.openAuth==='signup'?'signup':'signin';if(authMode==='signup'&&state.role==='Admin')state.role='Student';authOpen=true;app()});document.getElementById('closeAuth')?.addEventListener('click',()=>{authOpen=false;app()});document.getElementById('authOverlay')?.addEventListener('click',e=>{if(e.target.id==='authOverlay'){authOpen=false;app()}});document.querySelectorAll('[data-loginrole]').forEach(button=>button.onclick=()=>{state.role=button.dataset.loginrole;authOpen=true;app()});let form=document.getElementById('authForm');if(form)form.onsubmit=async e=>{e.preventDefault();let error=document.getElementById('authError'),identifier=document.getElementById('email').value.trim(),password=document.getElementById('password').value,name=document.getElementById('fullName')?.value.trim();if(!identifier){error.textContent='Enter your email address or phone number.';return}if(password.length<8){error.textContent='Use a password with at least 8 characters.';return}if(authMode==='signup'&&(!name||name.length<2)){error.textContent='Enter your full name.';return}let submit=document.getElementById('authSubmit');submit.disabled=true;error.textContent='';try{let response=await fetch(`/api/auth/${authMode==='signup'?'register':'login'}`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({identifier,password,name,role:state.role})}),data=await parseAuthResponse(response);if(!response.ok)throw new Error(data.error||'Sign-in could not be completed.');await activateAccount(data.user);await refreshPlatform();await refreshSharedData();authMode='signin';authOpen=false;view='Home';app();toast(authMode==='signup'?'Your account is ready. Welcome!':'Welcome back.')}catch(errorValue){error.textContent=errorValue.message.includes('Failed to fetch')?'Account service is unavailable. Start the InclusiveLearn server and try again.':errorValue.message}finally{let button=document.getElementById('authSubmit');if(button)button.disabled=false}};document.querySelectorAll('[data-provider]').forEach(button=>button.addEventListener('click',()=>{location.href=`/api/auth/oauth/${button.dataset.provider}?role=${encodeURIComponent(state.role)}`}));document.getElementById('explore')?.addEventListener('click',()=>{state.role='Student';state.name=roleDisplay.Student;state.email=roleEmails.Student;state.accountId=null;state.accountSession=false;state.guestMode=true;state.loggedIn=true;authOpen=false;persist();app()});document.getElementById('toggleAuth')?.addEventListener('click',()=>{authMode=authMode==='signup'?'signin':'signup';app()});document.getElementById('mobileMenu')?.addEventListener('click',()=>document.querySelector('.public-nav nav')?.classList.toggle('mobile-open'));document.getElementById('publicLanguage')?.addEventListener('change',e=>{state.language=e.target.value;persist();app()})}
function settingsPage(){return `<div class="welcome"><div><div class="eyebrow">ACCOUNT & PREFERENCES</div><h1>My profile and settings</h1><p>Update your account details and shape a more comfortable learning experience.</p></div><button class="btn" id="saveProfile">Save changes</button></div><div class="settings-grid"><section class="card"><div class="sectionhead"><div><h2>Profile details</h2><small>These details appear in your learning community.</small></div><span class="chip">${esc(state.role)}</span></div><div class="field"><label for="profileName">Full name</label><input id="profileName" value="${esc(state.name)}" autocomplete="name"></div><div class="field"><label for="profileEmail">Sign-in email or phone number</label><input id="profileEmail" value="${esc(state.email||'')}" autocomplete="email" readonly><small class="field-hint">Contact changes require account verification.</small></div><div class="field"><label>Workspace</label><input value="${esc(state.role)}" disabled></div>${state.role==='Student'?`<div class="field"><label for="guardianContact">Parent or guardian email / phone (optional)</label><input id="guardianContact" value="${esc(state.guardianContact||'')}" placeholder="The contact on the family account"><small class="field-hint">This shares your learning progress with that family account.</small></div>`:''}</section><section class="card"><div class="sectionhead"><div><h2>Accessibility & language</h2><small>Preferences apply across your workspace.</small></div><span class="chip green">Saved to profile</span></div><div class="settingrow"><div><b>Text size</b><p>Choose a comfortable reading size.</p></div><select id="fontSize" class="filter"><option value="100" ${state.font===100?'selected':''}>Standard</option><option value="112" ${state.font===112?'selected':''}>Large</option><option value="125" ${state.font===125?'selected':''}>Extra large</option></select></div><div class="settingrow"><div><b>High contrast</b><p>Increase text and background contrast.</p></div><input id="contrastToggle" class="toggle" type="checkbox" ${state.contrast?'checked':''} aria-label="High contrast"></div><div class="settingrow"><div><b>Read aloud</b><p>Use your device’s voice to read lessons.</p></div><input id="ttsToggle" class="toggle" type="checkbox" ${state.tts?'checked':''} aria-label="Read aloud"></div><div class="settingrow"><div><b>Speech input</b><p>Use speech input where supported.</p></div><input id="sttToggle" class="toggle" type="checkbox" ${state.stt?'checked':''} aria-label="Speech input"></div><div class="field"><label for="languageSelect">Interface language</label><select class="filter" id="languageSelect">${['English','Yorùbá','Kiswahili','Français'].map(x=>`<option ${state.language===x?'selected':''}>${x}</option>`).join('')}</select><small class="field-hint">Navigation and common controls change when you choose a language.</small></div></section></div>`}
function downloadReport(){let generated=new Date(),date=generated.toISOString().slice(0,10),rows=[],add=(...cells)=>rows.push(cells),csv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';add('InclusiveLearn Africa',`${state.role} report`);add('Generated',generated.toLocaleString());add('Prepared for',state.name);add('Account role',state.role);add('');add('SUMMARY','VALUE');if(state.role==='Admin'){add('Submitted content',platform.submissions.length);add('Awaiting review',platform.submissions.filter(x=>x.status==='Pending').length);add('Published resources',platform.published.length);add('Messages delivered',platform.messages.length)}else if(state.role==='Educator'){add('Learners in classroom',classroomRoster.length);add('Resources submitted',platform.submissions.filter(x=>x.author===state.name).length);add('Published resources',platform.published.length);add('Inbox messages',platform.messages.filter(x=>x.toRole==='Educator').length)}else if(state.role==='Parent'){add('Lessons in report',lessons.length+platform.published.length);add('Messages from educator',platform.messages.filter(x=>x.toRole==='Parent').length)}else{add('Lessons completed',Object.values(state.progress).filter(x=>x>=100).length);add('Saved offline',state.saved.length);add('Approved new resources',platform.published.length)}add('');add('LEARNING CONTENT','SUBJECT','GRADE','PROGRESS / STATUS','DETAILS');for(let l of [...lessons,...platform.published])add(l.title,l.subject,l.grade,`${state.progress[l.id]??l.progress??'Published'}${typeof(state.progress[l.id]??l.progress)==='number'?'%':''}`,l.description||l.desc||'');if(state.role==='Admin'||state.role==='Educator'){add('');add('CONTENT REVIEW','TYPE','SUBJECT','GRADE','STATUS','AUTHOR','SUBMITTED','REVIEW NOTE');platform.submissions.forEach(s=>add(s.title,s.type,s.subject,s.grade,s.status,s.author,s.createdAt,s.reviewNote||''))}if(state.role==='Educator'||state.role==='Parent'||state.role==='Admin'){add('');add('COMMUNICATION','FROM','ROLE','TO ROLE','DATE','MESSAGE');platform.messages.filter(m=>state.role==='Admin'||m.fromRole===state.role||m.toRole===state.role).forEach(m=>add(m.kind==='family-update'?'Family update':'Message',m.from,m.fromRole,m.toRole,m.time,m.text))}if(state.role==='Admin'){add('');add('PLATFORM ACTIVITY','DATE');platform.activity.forEach(a=>add(a.text,a.time))}let blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csv).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`inclusivelearn-${state.role.toLowerCase()}-report-${date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your detailed report has downloaded')}
function bindShared(){bindWorkflow();document.querySelector('[data-profile-signout]')?.addEventListener('click',()=>{state.loggedIn=false;authMode='signin';profileOpen=false;persist();app()});document.getElementById('profileButton')?.addEventListener('click',()=>{profileOpen=!profileOpen;notificationsOpen=false;app()});document.getElementById('languageQuick')?.addEventListener('change',e=>{state.language=e.target.value;persist();app();toast(`Language set to ${state.language}`)});document.getElementById('languageSelect')?.addEventListener('change',e=>{state.language=e.target.value;persist();app();toast(`Language set to ${state.language}`)});document.getElementById('saveProfile')?.addEventListener('click',()=>{let n=document.getElementById('profileName'),em=document.getElementById('profileEmail');if(n?.value.trim())state.name=n.value.trim();if(em?.value.trim())state.email=em.value.trim();platform.names=platform.names||{};platform.names[state.role]=state.name;persist();app();toast('Your profile and preferences are saved')});document.getElementById('mobileMenu')?.addEventListener('click',()=>document.querySelector('.public-nav nav')?.classList.toggle('mobile-open'));document.getElementById('publicLanguage')?.addEventListener('change',e=>{state.language=e.target.value;persist();app()})}
function mergeProgress(a={},b={}){let merged={...a};for(let [key,value] of Object.entries(b||{}))merged[key]=Math.max(Number(merged[key]||0),Number(value||0));return merged}
function queueServerSync(){if(!state.accountId)return;clearTimeout(syncTimer);syncTimer=setTimeout(async()=>{let payload={name:state.name,progress:state.progress||{},saved:state.saved||[],language:state.language||'English',accessibility:{font:state.font||100,contrast:Boolean(state.contrast),tts:Boolean(state.tts),stt:Boolean(state.stt)},guardianIdentifier:state.guardianContact||''};try{if(!navigator.onLine||state.offline){state.pendingSync=true;localStorage.setItem(`ila-account-${state.accountId}`,JSON.stringify(state));return}let response=await fetch('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',cache:'no-store',body:JSON.stringify(payload)});if(!response.ok)throw new Error('sync failed');state.pendingSync=false;localStorage.setItem(`ila-account-${state.accountId}`,JSON.stringify(state));let badge=document.getElementById('connect');if(badge){badge.classList.remove('offline');badge.classList.add('online');badge.textContent='● Synced'}}catch{state.pendingSync=true;localStorage.setItem(`ila-account-${state.accountId}`,JSON.stringify(state));let badge=document.getElementById('connect');if(badge){badge.classList.remove('online');badge.classList.add('offline');badge.textContent='◉ Offline · Sync pending'}}},450)}
async function activateAccount(user){let local=JSON.parse(localStorage.getItem(`ila-account-${user.id}`)||'null')||{};state={...seed,...local,accountId:user.id,accountSession:true,guestMode:false,loggedIn:true,role:user.role,name:user.name,email:user.identifier,progress:local.progress||{},saved:local.saved||[],messages:local.messages||[],language:local.language||user.language||'English'};try{let response=await fetch('/api/sync',{credentials:'same-origin',cache:'no-store'});if(response.ok){let serverData=await response.json();state.progress=mergeProgress(serverData.learning?.progress,state.progress);state.saved=[...new Set([...(serverData.learning?.saved||[]),...(state.saved||[])])];state.guardianContact=local.guardianContact||serverData.guardianIdentifier||'';state.language=local.language||serverData.preferences?.language||user.language||'English';state.font=local.font||serverData.preferences?.font||user.accessibility?.font||100;state.contrast=local.contrast??serverData.preferences?.contrast??false;state.tts=local.tts??serverData.preferences?.tts??false;state.stt=local.stt??serverData.preferences?.stt??false}}catch{}state.roleNames=state.roleNames||{};state.roleNames[state.role]=state.name;state.loggedIn=true;persist()}
async function syncWhenOnline(){if(!state.accountId||!navigator.onLine)return;await queueServerSync()}
function addSpeechInputControls(root){root.querySelectorAll('textarea:not([data-speech-ready])').forEach(field=>{field.dataset.speechReady='true';let wrap=document.createElement('div');wrap.className='speech-field';field.parentNode.insertBefore(wrap,field);wrap.append(field);let button=document.createElement('button');button.type='button';button.className='speech-input-btn';button.setAttribute('aria-label','Dictate into this field');button.innerHTML='<i class="fa-solid fa-microphone" aria-hidden="true"></i><span>Dictate</span>';wrap.append(button);button.addEventListener('click',()=>startSpeechInput(field,button))})}
function startSpeechInput(field,button){let Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Speech input is not supported in this browser.');return}let recognition=new Recognition();recognition.lang=({English:'en-US','Yorùbá':'yo-NG',Kiswahili:'sw-KE',Français:'fr-FR'})[state.language]||'en-US';recognition.interimResults=false;recognition.maxAlternatives=1;button.classList.add('listening');button.querySelector('span').textContent='Listening…';recognition.onresult=event=>{let phrase=event.results[0][0].transcript;field.value=`${field.value}${field.value.trim()?' ':''}${phrase}`;field.dispatchEvent(new Event('input',{bubbles:true}))};recognition.onerror=()=>toast('Could not hear that. Try again or type your message.');recognition.onend=()=>{button.classList.remove('listening');button.querySelector('span').textContent='Dictate'};recognition.start()}
async function refreshPlatform(){if(!state.accountId||!navigator.onLine)return;try{let response=await fetch('/api/platform',{credentials:'same-origin',cache:'no-store'});if(!response.ok)return;let data=await response.json();platform={...platform,...data,messages:platform.messages||[],names:platform.names||{},submissions:data.submissions||[],published:data.published||[],assignments:data.assignments||[],assignmentResponses:data.assignmentResponses||[],notifications:[...(data.notifications||[]),...(platform.notifications||[]).filter(item=>!data.notifications?.some(remote=>remote.id===item.id))],activity:data.activity||[]};localStorage.setItem(PLATFORM_KEY,JSON.stringify(platform));app()}catch{}}
async function syncPlatform(){if(!state.accountId||!navigator.onLine)return false;try{let response=await fetch('/api/platform',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({submissions:platform.submissions||[],assignments:platform.assignments||[],assignmentResponses:platform.assignmentResponses||[],activity:platform.activity||[]})}),data;try{data=await response.json()}catch{throw new Error('The learning platform returned an unreadable response.')}if(!response.ok)throw new Error(data.error||'Your changes could not be synchronized.');await refreshPlatform();return true}catch(error){toast(error.message||'Your changes are saved on this device and will sync when the connection returns.');return false}}async function refreshSharedData(){if(!state.accountId||!navigator.onLine)return;let changed=false;try{let contactResponse=await fetch('/api/contacts',{credentials:'same-origin',cache:'no-store'});if(contactResponse.ok){contacts=(await contactResponse.json()).contacts||[];changed=true}}catch{}try{let response=await fetch('/api/messages',{credentials:'same-origin',cache:'no-store'});if(response.ok){let data=await response.json();remoteMessages=data.messages||[];for(let message of remoteMessages)if(!platform.messages.some(old=>old.id===message.id))platform.messages.unshift(message);changed=true}}catch{}if(state.role==='Parent'){try{let response=await fetch('/api/parent/child',{credentials:'same-origin',cache:'no-store'});if(response.ok){let data=await response.json();parentChild=data.child;changed=true}}catch{}}if(state.role==='Educator'||state.role==='Admin'){try{let response=await fetch('/api/classroom/progress',{credentials:'same-origin',cache:'no-store'});if(response.ok){let data=await response.json();classroomRoster=data.students||[];changed=true}}catch{}}if(changed)app()}
async function logoutAccount(){try{await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'})}catch{}state.accountId=null;state.accountSession=false;state.guestMode=false;state.loggedIn=false;profileOpen=false;notificationsOpen=false;persist();app()}
function initialiseAccount(){let params=new URLSearchParams(location.search);window.addEventListener('focus',()=>{refreshPlatform();refreshSharedData()});window.addEventListener('online',()=>{state.pendingSync=false;syncWhenOnline();refreshPlatform();refreshSharedData()});if(state.accountId)setInterval(()=>{refreshPlatform();refreshSharedData()},25000);if(params.get('authError')){authMode='signin';authOpen=true;app();setTimeout(()=>toast(params.get('authError')==='provider_setup'?`${params.get('provider')||'Social'} sign-in needs provider credentials in this deployment.`:'Social sign-in could not be completed.'),250)}if(!state.guestMode)state.loggedIn=Boolean(state.accountSession);app();if(!navigator.onLine)return;fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'}).then(response=>response.json()).then(async data=>{if(data.user){await activateAccount(data.user);await refreshPlatform();await refreshSharedData();app();if(params.get('social'))toast('Your social account is connected.')}else if(!state.guestMode){state.loggedIn=false;state.accountSession=false;state.accountId=null;app()}}).catch(()=>{});window.addEventListener('online',syncWhenOnline)}
function parentLinkCard(){return `<section class="card parent-link-card"><div class="sectionhead"><div><h2>Link a learner</h2><small>Enter the learner’s sign-in email or phone. They approve before progress is shared.</small></div><span class="chip">Private by approval</span></div><form id="parentLinkForm" class="parent-link-form"><div class="field"><label for="learnerIdentifier">Learner email or phone number</label><input id="learnerIdentifier" name="identifier" placeholder="learner@example.org or +254…" required></div><button class="btn" type="submit">Request access</button></form><p id="parentLinkError" class="field-hint" role="status"></p>${parentRequests.map(item=>`<div class="settingrow"><span>${esc(item.learner)}</span><span class="chip ${item.status==='Approved'?'green':''}">${esc(item.status)}</span></div>`).join('')}</section>`}
function parentPage(){let child=parentChild,p=child?.progress||{},done=Object.values(p).filter(v=>Number(v)>=100).length,started=Object.values(p).filter(v=>Number(v)>0).length,avg=started?Math.round(Object.values(p).reduce((a,v)=>a+Number(v),0)/started):0;return `<div class="welcome"><div><div class="eyebrow">FAMILY SPACE</div><h1>${child?`Learning with ${esc(child.name)}`:`Hello, ${esc(state.name.split(' ')[0])}`}</h1><p>${child?'Follow progress and stay connected with the educator.':'Request a link to your learner. They approve before progress is shared.'}</p></div><button class="btn" data-view="Messages">✉ Message educator</button></div>${parentLinkCard()}<div class="grid stats"><div class="card stat"><div><div class="label">Completed lessons</div><div class="value">${done}</div><div class="hint">Learner progress</div></div></div><div class="card stat"><div><div class="label">Average progress</div><div class="value">${avg}%</div><div class="hint">Across ${started} started lessons</div></div></div><div class="card stat"><div><div class="label">Saved offline</div><div class="value">${child?.saved?.length||0}</div><div class="hint">Materials on learner’s device</div></div></div></div>${child?`<section class="card"><div class="sectionhead"><h2>${esc(child.name)}’s progress</h2><button class="textbtn" data-view="Child progress">Open full report →</button></div>${lessons.map(l=>{let v=Number(p[l.id]||0);return `<div class="settingrow"><div style="flex:1"><b>${esc(l.title)}</b><p>${esc(l.subject)} · ${esc(l.grade)}</p><div class="progress"><i style="width:${v}%"></i></div></div><strong>${v}%</strong></div>`}).join('')}</section>`:`<div class="card empty-state"><h2>No learner account linked</h2><p>Enter the learner’s sign-in email or phone above. They can approve from their notifications.</p></div>`}`}
function parentProgressPage(){let child=parentChild;if(!child)return `<div class="welcome"><div><div class="eyebrow">FAMILY PROGRESS</div><h1>Learning report</h1><p>Request access to a learner’s progress. They approve the link from notifications.</p></div></div>${parentLinkCard()}<div class="card empty-state"><h2>No learner account linked</h2><p>Reports appear here after the learner approves your request.</p></div>`;let rows=lessons.map(l=>({l,v:Number(child.progress?.[l.id]||0)}));return `<div class="welcome"><div><div class="eyebrow">FAMILY PROGRESS · ${esc(child.name)}</div><h1>Learning report</h1><p>Progress saved on the learner’s account${child.updatedAt?` · Synced ${new Date(child.updatedAt).toLocaleString()}`:''}.</p></div><button class="btn light" id="downloadReport">↓ Download report</button></div>${parentLinkCard()}<div class="card"><div class="sectionhead"><h2>Module progress</h2><span class="chip">${rows.filter(r=>r.v>=100).length} completed</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Lesson</th><th>Subject</th><th>Progress</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.l.title)}</td><td>${esc(r.l.subject)}</td><td>${r.v}%</td></tr>`).join('')}</tbody></table></div></div>`}
function notificationDropdown(){let items=(platform.notifications||[]).filter(n=>n.role===state.role&&(!n.accountId||n.accountId===state.accountId)).sort((a,b)=>(Date.parse(b.createdAt||b.time)||0)-(Date.parse(a.createdAt||a.time)||0)).slice(0,12),unread=items.filter(n=>!n.read).length;return `<div class="notification-panel"><div class="notification-head"><div><b>Notifications</b><small>${unread?`${unread} unread updates`:'All caught up'}</small></div><button class="textbtn" id="readAllNotifications" ${unread?'':'disabled'}>Mark all read</button></div>${items.length?items.map(n=>`<button class="notification-item ${n.read?'read':''}" data-notice="${esc(n.id)}"><span class="notification-icon">${n.type==='learner-link-request'?'🔗':n.title.toLowerCase().includes('message')||n.title.toLowerCase().includes('update')?'✉':'✦'}</span><span><b>${esc(n.title)}</b><small>${esc(n.body)} · ${esc(n.time||'')}</small></span>${n.read?'':'<i aria-label="Unread"></i>'}</button>`).join(''):'<div class="notification-empty">Messages and learning updates will appear here.</div>'}</div>`}
const settingsBeforeLinkRequests=settingsPage;
settingsPage=function(){let html=settingsBeforeLinkRequests();if(state.role!=='Student'||!linkRequests.length)return html;let i=html.lastIndexOf('</div>'),panel=`<section class="card link-approval-card"><div class="sectionhead"><div><h2>Parent access requests</h2><small>Approve only family members you want to share progress with.</small></div></div>${linkRequests.map(r=>`<div class="settingrow"><div style="flex:1"><b>${esc(r.parentName)}</b><p>Would like to view your learning progress.</p></div><button class="btn soft" data-link-request="${esc(r.id)}" data-decision="Approved">Approve</button><button class="btn danger" data-link-request="${esc(r.id)}" data-decision="Declined">Decline</button></div>`).join('')}</section>`;return html.slice(0,i)+panel+html.slice(i)};
const previousBindWorkflow=bindWorkflow;
bindWorkflow=function(){previousBindWorkflow();document.getElementById('readAllNotifications')?.addEventListener('click',async()=>{for(const n of platform.notifications||[])if(n.role===state.role&&(!n.accountId||n.accountId===state.accountId))n.read=true;if(state.accountId)try{await fetch('/api/notifications/read',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({all:true})})}catch{}state.unread=0;persist();notificationsOpen=true;app()});document.querySelectorAll('[data-notice]').forEach(b=>b.addEventListener('click',async()=>{let n=platform.notifications.find(x=>x.id===b.dataset.notice);if(n)n.read=true;if(state.accountId)try{await fetch('/api/notifications/read',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:[b.dataset.notice]})})}catch{}view=n?.target==='Settings'?'Settings':n?.target==='Child progress'?'Child progress':'Messages';notificationsOpen=false;persist();await refreshSharedData();await refreshPlatform();app()}));document.getElementById('parentLinkForm')?.addEventListener('submit',async e=>{e.preventDefault();let out=document.getElementById('parentLinkError');out.textContent='Sending request…';try{let response=await fetch('/api/parent/link',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({identifier:new FormData(e.currentTarget).get('identifier')})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not request access.');out.textContent=data.status==='Approved'?`${data.learner} is linked.`:`Request sent to ${data.learner}. They need to approve access.`;await refreshSharedData();app()}catch(err){out.textContent=err.message}});document.querySelectorAll('[data-link-request]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{let response=await fetch('/api/parent/link-requests/respond',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:b.dataset.linkRequest,decision:b.dataset.decision})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not update request.');await refreshSharedData();await refreshPlatform();app();toast(data.status==='Approved'?'Progress sharing approved.':'Request declined.')}catch(err){toast(err.message)}}))};
async function refreshSharedData(){if(!state.accountId||!navigator.onLine)return;let changed=false;try{let c=await fetch('/api/contacts',{credentials:'same-origin',cache:'no-store'});if(c.ok){contacts=(await c.json()).contacts||[];changed=true}}catch{}try{let m=await fetch('/api/messages',{credentials:'same-origin',cache:'no-store'});if(m.ok){remoteMessages=(await m.json()).messages||[];for(let x of remoteMessages)if(!platform.messages.some(y=>y.id===x.id))platform.messages.unshift(x);changed=true}}catch{}if(state.role==='Parent'){try{let [a,b]=await Promise.all([fetch('/api/parent/child',{credentials:'same-origin',cache:'no-store'}),fetch('/api/parent/requests',{credentials:'same-origin',cache:'no-store'})]);if(a.ok){parentChild=(await a.json()).child;changed=true}if(b.ok){parentRequests=(await b.json()).requests||[];changed=true}}catch{}}if(state.role==='Student'){try{let r=await fetch('/api/parent/link-requests',{credentials:'same-origin',cache:'no-store'});if(r.ok){linkRequests=(await r.json()).requests||[];changed=true}}catch{}}if(state.role==='Educator'||state.role==='Admin'){try{let r=await fetch('/api/classroom/progress',{credentials:'same-origin',cache:'no-store'});if(r.ok){classroomRoster=(await r.json()).students||[];changed=true}}catch{}}if(changed)app()}

let usageData=null,usageLoading=false,usageRangeDays=30;
function adminUsagePage(){if(usageLoading)return `<div class="welcome"><div><div class="eyebrow">ADMINISTRATION · ANALYTICS</div><h1>Usage reports</h1><p>Loading the latest platform activity…</p></div></div><div class="card"><div class="progress"><i style="width:72%"></i></div></div>`;if(!usageData)return `<div class="welcome"><div><div class="eyebrow">ADMINISTRATION · ANALYTICS</div><h1>Usage reports</h1><p>See how learners, educators, families, and learning materials use the platform.</p></div><button class="btn" id="refreshUsage">Refresh report</button></div><div class="card empty-state"><h2>Usage data is not loaded</h2><p>Choose Usage reports again or refresh to load account activity.</p></div>`;let d=usageData,roles=d.byRole||{},eng=d.engagement||{},content=d.content||{},comms=d.communication||{},tasks=d.assignments||{};let cards=[['Registered accounts',Object.values(roles).reduce((a,v)=>a+v,0),'Across all four roles'],['Active learners',d.activeLearners||0,`Learning activity in ${d.days} days`],['Lessons completed',eng.lessonsCompleted||0,`${eng.lessonsStarted||0} started`],['Messages delivered',comms.messages||0,'Across the learning community']];return `<div class="welcome"><div><div class="eyebrow">ADMINISTRATION · ANALYTICS</div><h1>Usage reports</h1><p>Platform activity and learning engagement · generated ${new Date(d.generatedAt).toLocaleString()}</p></div><div style="display:flex;gap:.7rem;align-items:center"><select id="usageRange" class="filter" aria-label="Activity period"><option value="7" ${d.days===7?'selected':''}>Last 7 days</option><option value="30" ${d.days===30?'selected':''}>Last 30 days</option><option value="90" ${d.days===90?'selected':''}>Last 90 days</option><option value="365" ${d.days===365?'selected':''}>Last 12 months</option></select><button class="btn light" id="refreshUsage">Refresh</button><button class="btn" id="downloadUsageReport">↓ Download CSV</button></div></div><div class="grid stats">${cards.map(([label,value,hint])=>`<div class="card stat"><div><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></div><div class="staticon">${label==='Registered accounts'?'♙':label==='Active learners'?'↗':label==='Lessons completed'?'✓':'✉'}</div></div>`).join('')}</div><div class="grid cols"><section class="card"><div class="sectionhead"><div><h2>Accounts by role</h2><small>Registered accounts in this platform</small></div></div>${[['Students',roles.Student],['Educators',roles.Educator],['Parents',roles.Parent],['Administrators',roles.Admin]].map(([name,value])=>`<div class="settingrow"><b>${name}</b><span class="chip green">${value||0}</span></div>`).join('')}</section><section class="card"><div class="sectionhead"><div><h2>Learning and content</h2><small>Progress and publication overview</small></div></div>${[['Lessons started',eng.lessonsStarted],['Saved for offline',eng.savedOffline],['Published materials',content.published],['Awaiting review',content.pending],['Rejected submissions',content.rejected]].map(([name,value])=>`<div class="settingrow"><span>${name}</span><b>${value||0}</b></div>`).join('')}</section></div><section class="card"><div class="sectionhead"><div><h2>Assignments & recent activity</h2><small>${tasks.created||0} assignments · ${tasks.responses||0} learner responses</small></div></div>${(d.recentActivity||[]).length?`<div class="tablewrap"><table class="table"><thead><tr><th>Activity</th><th>Date</th></tr></thead><tbody>${d.recentActivity.map(item=>`<tr><td>${esc(item.text||'Platform activity')}</td><td>${esc(item.time||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><b>No recent activity yet</b><p>Content submissions, approvals, and other platform activity will appear here.</p></div>'}</section>`}
async function loadAdminUsage(days=usageRangeDays){if(state.role!=='Admin')return;usageRangeDays=days;usageLoading=true;usageData=null;app();try{let response=await fetch(`/api/admin/usage?days=${days}`,{credentials:'same-origin',cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error||'Usage report could not be loaded.');usageData=data;usageLoading=false;app()}catch(error){usageLoading=false;usageData=null;app();toast(error.message)}}
function downloadUsageReport(){if(!usageData){toast('Load the usage report before downloading.');return}let d=usageData,rows=[['InclusiveLearn Africa','Admin usage report'],['Generated',new Date(d.generatedAt).toLocaleString()],['Activity period',`Last ${d.days} days`],[],['Accounts by role','Count'],...Object.entries(d.byRole||{}),[],['Learning engagement','Count'],...Object.entries(d.engagement||{}),['Active learners',d.activeLearners],[],['Content','Count'],...Object.entries(d.content||{}),[],['Communication','Count'],...Object.entries(d.communication||{}),[],['Assignments','Count'],...Object.entries(d.assignments||{}),[],['Recent activity','Date'],...(d.recentActivity||[]).map(item=>[item.text,item.time])];let csv=v=>'"'+String(v??'').replace(/"/g,'""')+'"',blob=new Blob(['\uFEFF'+rows.map(row=>row.map(csv).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`inclusivelearn-usage-${d.days}-days-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Usage report downloaded')}
const previousUsageWorkflow=bindWorkflow;
bindWorkflow=function(){previousUsageWorkflow();document.querySelectorAll('[data-view="Usage reports"]').forEach(button=>button.addEventListener('click',()=>loadAdminUsage(usageRangeDays)));document.getElementById('usageRange')?.addEventListener('change',event=>loadAdminUsage(Number(event.target.value)));document.getElementById('refreshUsage')?.addEventListener('click',()=>loadAdminUsage(usageRangeDays));document.getElementById('downloadUsageReport')?.addEventListener('click',downloadUsageReport)};
const previousContentWorkflow=bindWorkflow;
bindWorkflow=function(){previousContentWorkflow();document.querySelectorAll('[data-delete-content]').forEach(button=>button.addEventListener('click',async()=>{let item=platform.published.find(resource=>resource.id===button.dataset.deleteContent);if(!item||!confirm(`Delete “${item.title}” from student learning spaces?`))return;button.disabled=true;try{let response=await fetch(`/api/platform/published/${encodeURIComponent(item.id)}`,{method:'DELETE',credentials:'same-origin',headers:{'Content-Type':'application/json'}}),data=await response.json();if(!response.ok)throw new Error(data.error||'Published content could not be deleted.');if(state.savedResources)delete state.savedResources[item.id];state.saved=state.saved.filter(id=>id!==item.id);persist();await refreshPlatform();app();toast('Published content deleted from student spaces.')}catch(error){button.disabled=false;toast(error.message)}}))};

const featuredLessonVideos={
 plants:{url:'https://www.youtube.com/watch?v=tkFPyue5X3Q',title:'How Does a Seed Become a Plant?',source:'SciShow Kids'},
 fractions:{url:'https://www.youtube.com/watch?v=Z3SyYL60ELQ',title:'Fractions for Kids: Halves & Fourths',source:'Khan Academy Kids'},
 water:{url:'https://www.youtube.com/watch?v=vD-ZwMjRDPU',title:'The Water Cycle',source:'SciShow Kids'}
};
for(const lesson of lessons){let video=featuredLessonVideos[lesson.id];if(video)Object.assign(lesson,{videoUrl:video.url,videoTitle:video.title,videoSource:video.source})}
const courseCardWithoutVideo=courseCard;
courseCard=function(lesson){let card=courseCardWithoutVideo(lesson);if(!lesson.videoUrl)return card;let player=videoPlayer(lesson.videoUrl,`Watch: ${lesson.videoTitle||lesson.title}`);let credit=`<small class="video-credit">Video: ${esc(lesson.videoSource||'Learning library')} · Opens from ${esc(lesson.lang||'English')} lesson</small>`;return card.replace('<div class="coursefoot">',`${player}${credit}<div class="coursefoot">`)};
const lessonPageWithoutVideo=lessonPage;
lessonPage=function(id){let lesson=lessons.find(item=>item.id===id),page=lessonPageWithoutVideo(id);if(!lesson?.videoUrl)return page;let player=videoPlayer(lesson.videoUrl,`Watch: ${lesson.videoTitle||lesson.title}`),credit=`<small class="video-credit">Video: ${esc(lesson.videoSource||'Learning library')}</small>`;return page.replace('<div class="lesson-narration" id="lessonNarration">',`${player}${credit}<div class="lesson-narration" id="lessonNarration">`)};

initialiseAccount();

setInterval(()=>{const heading=document.querySelector('[data-student-greeting]');if(heading)heading.textContent=timeGreeting()+', '+state.name.split(' ')[0]+' 👋';const date=document.querySelector('[data-student-date]');if(date)date.textContent=new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'})},60000);
